/**
 * Version Check Utilities
 * Checks npm registry for the latest lua-cli version and caches the result.
 * Used by the update command (LUA-123) and the outdated version warning (LUA-124).
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'fs';
import { compareVersions, parseVersion } from './semver.js';
import { CLI_CONFIG_DIR, VERSION_CHECK_FILE } from '../config/constants.js';
const CHECK_INTERVAL_MS = 24 * 60 * 60 * 1000; // 24 hours
const NPM_REGISTRY_BASE = 'https://registry.npmjs.org/lua-cli';
const FETCH_TIMEOUT_MS = 3000;

/**
 * Get the npm registry URL for the appropriate dist-tag.
 * If currentVersion has a pre-release tag (e.g. "alpha"), use that dist-tag.
 * Otherwise use "latest" (stable releases).
 */
function getRegistryUrl(currentVersion: string): string {
  const { preRelease } = parseVersion(currentVersion);
  if (preRelease) {
    // Extract tag name from pre-release (e.g. "alpha.9" → "alpha", "beta.1" → "beta")
    const tag = preRelease.split('.')[0].replace(/[0-9]/g, '');
    if (tag) return `${NPM_REGISTRY_BASE}/${tag}`;
  }
  return `${NPM_REGISTRY_BASE}/latest`;
}

interface VersionCheckCache {
  latestVersion: string;
  checkedAt: number;
}

/**
 * Read cached version check result.
 * Returns null if cache is missing, corrupt, or expired.
 */
export function getCachedVersionCheck(): VersionCheckCache | null {
  try {
    if (!existsSync(VERSION_CHECK_FILE)) return null;
    const raw = readFileSync(VERSION_CHECK_FILE, 'utf8');
    const cache: VersionCheckCache = JSON.parse(raw);
    if (Date.now() - cache.checkedAt > CHECK_INTERVAL_MS) return null;
    return cache;
  } catch {
    return null;
  }
}

/**
 * Save version check result to cache file.
 */
export function saveCachedVersionCheck(latestVersion: string): void {
  try {
    if (!existsSync(CLI_CONFIG_DIR)) {
      mkdirSync(CLI_CONFIG_DIR, { recursive: true });
    }
    writeFileSync(VERSION_CHECK_FILE, JSON.stringify({ latestVersion, checkedAt: Date.now() }), 'utf8');
  } catch {
    // Silently ignore write failures (permissions, disk full, etc.)
  }
}

/**
 * Fetch the latest version from npm registry.
 * Uses the dist-tag matching the current version's pre-release channel (e.g. "alpha").
 * Returns null on any failure (network, timeout, parse error).
 */
export async function fetchLatestVersion(currentVersion?: string): Promise<string | null> {
  try {
    const url = getRegistryUrl(currentVersion ?? '0.0.0');
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
    const response = await fetch(url, { signal: controller.signal });
    clearTimeout(timeout);
    if (!response.ok) return null;
    const data = (await response.json()) as { version?: string };
    return data.version ?? null;
  } catch {
    return null;
  }
}

/**
 * Check if an update is available. Uses 24h cache to avoid hitting npm on every run.
 */
export async function isUpdateAvailable(
  currentVersion: string
): Promise<{ available: boolean; latest: string | null }> {
  const cached = getCachedVersionCheck();
  if (cached) {
    return {
      available: compareVersions(currentVersion, cached.latestVersion) < 0,
      latest: cached.latestVersion,
    };
  }

  const latest = await fetchLatestVersion(currentVersion);
  if (!latest) return { available: false, latest: null };

  saveCachedVersionCheck(latest);
  return {
    available: compareVersions(currentVersion, latest) < 0,
    latest,
  };
}

/**
 * Print a boxed update warning to stderr (so piped --json stdout is not corrupted).
 */
export function printUpdateWarning(currentVersion: string, latestVersion: string): void {
  const msg = `Update available: ${currentVersion} → ${latestVersion}`;
  const tip = 'Run `lua update` to install the latest version';
  const width = Math.max(msg.length, tip.length) + 6;
  const pad = (s: string) => s + ' '.repeat(width - s.length);

  console.error('');
  console.error(`  ╭${'─'.repeat(width)}╮`);
  console.error(`  │${' '.repeat(width)}│`);
  console.error(`  │${pad('   ' + msg)}│`);
  console.error(`  │${pad('   ' + tip)}│`);
  console.error(`  │${' '.repeat(width)}│`);
  console.error(`  ╰${'─'.repeat(width)}╯`);
  console.error('');
}
