import type { VoiceDispatchInput, VoiceDispatchOutput } from '@lua/shared-types';
import { DevVersionResponse } from '../interfaces/dev.js';
import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';
import {
  GetVoicesResponse,
  DeleteVoiceResponse,
  CreateVoiceRequest,
  CreateVoiceResponse,
  PushVoiceVersionRequest,
  GetVoiceVersionsResponse,
} from '../interfaces/voices.js';

/**
 * Voice API client — CRUD + version management for code-defined LuaVoice
 * agents on the developer API.
 */
export default class VoiceApi extends HttpClient {
  private apiKey: string;
  private agentId: string;

  constructor(baseUrl: string, apiKey: string, agentId: string) {
    super(baseUrl);
    this.apiKey = apiKey;
    this.agentId = agentId;
  }

  async getVoices(): Promise<ApiResponse<GetVoicesResponse>> {
    return this.httpGet<GetVoicesResponse>(`/developer/voice-agents/${this.agentId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  async createVoice(voiceData: CreateVoiceRequest): Promise<ApiResponse<CreateVoiceResponse>> {
    return this.httpPost<CreateVoiceResponse>(`/developer/voice-agents/${this.agentId}`, voiceData, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  async pushVoice(voiceId: string, versionData: PushVoiceVersionRequest): Promise<ApiResponse<DevVersionResponse>> {
    return this.httpPost<DevVersionResponse>(
      `/developer/voice-agents/${this.agentId}/${voiceId}/version`,
      versionData,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  async getVoiceVersions(voiceId: string): Promise<ApiResponse<GetVoiceVersionsResponse>> {
    return this.httpGet<GetVoiceVersionsResponse>(`/developer/voice-agents/${this.agentId}/${voiceId}/versions`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  async publishVoiceVersion(
    voiceId: string,
    version: string
  ): Promise<ApiResponse<{ message: string; voiceId: string; activeVersionId: string; publishedAt: string }>> {
    return this.httpPut<{ message: string; voiceId: string; activeVersionId: string; publishedAt: string }>(
      `/developer/voice-agents/${this.agentId}/${voiceId}/${version}/publish`,
      undefined,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  async deleteVoice(voiceId: string): Promise<ApiResponse<DeleteVoiceResponse>> {
    return this.httpDelete<DeleteVoiceResponse>(`/developer/voice-agents/${this.agentId}/${voiceId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Place an outbound voice call. Wraps `POST /developer/voice-agents/:agentId/dispatch`
   * — body validated server-side (target, voice ownership, quota), then
   * forwarded to the lua-livekit worker which allocates the room and dials.
   */
  async dispatch(input: VoiceDispatchInput): Promise<ApiResponse<VoiceDispatchOutput>> {
    return this.httpPost<VoiceDispatchOutput>(`/developer/voice-agents/${this.agentId}/dispatch`, input, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Sandbox helper: throws on non-success and returns the unwrapped output.
   * Mirrors the shape `AgentsApiService.invokeForSandbox` exposes so the
   * `Voice` namespace in `api-exports.ts` stays a one-liner.
   */
  async dispatchForSandbox(input: VoiceDispatchInput): Promise<VoiceDispatchOutput> {
    const result = await this.dispatch(input);
    if (!result.success) {
      throw new Error(result.error?.message || 'Voice dispatch failed');
    }
    if (!result.data) {
      throw new Error('Voice dispatch failed: empty response');
    }
    return result.data;
  }
}
