/**
 * Base Primitive Handler
 *
 * Abstract base class providing common implementation for primitive handlers.
 * Subclasses implement primitive-specific logic (API calls, active checks, etc.)
 *
 * YAML types come from yaml.types.ts (YamlConfigSkill, YamlConfigWebhook, etc.)
 * Server types come from interfaces/ (Skill, Webhook, Job, etc.)
 */

import { PrimitiveKind, CompilationManifest, ManifestPrimitive } from '../compiler/types.js';
import { YamlConfig } from '../types/yaml.types.js';
import { readYamlConfig, writeYamlConfig } from '../utils/files.js';
import { SKILL_DEFAULTS } from '../config/compile.constants.js';
import {
  findPrimitive,
  loadArtifact,
  compressForPush,
  compressForPushRaw,
  getPrimitivesByKind,
} from '../utils/artifact-loader.js';
import { hashBundle } from '../utils/bundle-upload.js';
import { maxSemver } from '../utils/semver.js';
import { AuthenticationError } from '../errors/auth.error.js';
import type {
  VersionedPrimitiveHandler,
  PrimitiveHandler,
  SyncResult,
  ServerSyncData,
  YamlPrimitiveConfig,
} from './types.js';

/** Default version for new primitives */
export const DEFAULT_VERSION = SKILL_DEFAULTS.VERSION;

// =============================================================================
// BASE VERSIONED HANDLER
// =============================================================================

/**
 * Abstract base class for versioned primitive handlers.
 *
 * T = the YAML item type (from yaml.types.ts, e.g. YamlConfigSkill).
 *     Must have at least { name: string; version: string; [idField]: string }.
 */
export abstract class BaseVersionedHandler<
  T extends { name: string; version: string },
  TPushData = Record<string, unknown>,
> implements VersionedPrimitiveHandler<T> {
  abstract readonly kind: PrimitiveKind;
  abstract readonly displayName: string;
  abstract readonly displayNamePlural: string;
  abstract readonly deleteCommand: string;
  abstract readonly yamlConfig: YamlPrimitiveConfig;

  protected abstract getApi(apiKey: string, agentId: string): unknown;
  protected abstract fetchFromServer(api: unknown): Promise<any[] | null>;
  /**
   * Strip a YAML item to only the canonical fields: name, version, [idField].
   * Override if your YAML type has additional fields.
   */
  cleanItem(item: T): T {
    return {
      name: item.name || '',
      version: item.version || DEFAULT_VERSION,
      [this.yamlConfig.idField]: this.getItemId(item) || '',
    } as T;
  }

  /**
   * Whether a server entity is considered active (for orphan detection).
   * Default: true. Override for primitives with active/status fields.
   */
  isActive(_serverItem: any): boolean {
    return true;
  }

  /**
   * Get the active version string from a server entity.
   * Default: finds version with isActive === true. Override for different field names.
   */
  getActiveVersion(serverItem: any): string | null {
    const active = serverItem.versions?.find((v: any) => v.isActive === true);
    return active?.version ?? null;
  }

  protected getServerItemName(item: any): string {
    return item.name || 'unknown';
  }

  protected shouldConsiderForOrphan(_item: any): boolean {
    return true;
  }

  // ===========================================================================
  // SERVER SYNC
  // ===========================================================================

  /**
   * Fetches server items and merges with local YAML for interactive delete/trigger prompts.
   * Local items take priority for shared IDs; server-only orphans are appended as minimal
   * cleanItem objects. On server failure, returns local items only with an empty orphan set.
   */
  async fetchMergedForInteraction(
    apiKey: string,
    agentId: string,
    config: YamlConfig
  ): Promise<{ merged: T[]; orphanIds: Set<string>; serverFailed: boolean }> {
    const serverData = await this.fetchServerState(apiKey, agentId);
    const localItems = this.getFromYaml(config);

    if (!serverData.serverItems) {
      return { merged: localItems, orphanIds: new Set<string>(), serverFailed: true };
    }

    const serverItems = serverData.serverItems;
    const orphanIds = new Set(
      serverItems.filter((s) => !localItems.some((l) => this.getItemId(l) === s.id)).map((s) => s.id as string)
    );

    const merged = serverItems.map((s) => {
      const local = localItems.find((l) => this.getItemId(l) === s.id);
      if (local) return local;
      return this.cleanItem({
        name: s.name,
        version: this.getActiveVersion(s) ?? '',
        [this.yamlConfig.idField]: s.id,
      } as unknown as T);
    });

    return { merged, orphanIds, serverFailed: false };
  }

  /** Phase 1 of parallel sync: fetch server state (HTTP only, no YAML writes) */
  async fetchServerState(apiKey: string, agentId: string): Promise<ServerSyncData> {
    try {
      const api = this.getApi(apiKey, agentId);
      const serverItems = await this.fetchFromServer(api);
      return { serverItems };
    } catch (error) {
      if (AuthenticationError.isAuthenticationError(error)) throw error;
      return { serverItems: null, fetchError: error instanceof Error ? error.message : String(error) };
    }
  }

  /**
   * Phase 2 of parallel sync: apply fetched data to YAML.
   * Optionally creates missing primitives on server if apiKey+agentId provided.
   */
  async applySyncToYaml(
    serverData: ServerSyncData,
    config: YamlConfig | null,
    manifest?: CompilationManifest,
    apiCredentials?: { apiKey: string; agentId: string }
  ): Promise<SyncResult> {
    const messages: string[] = [];
    let yamlUpdated = false;
    let orphanedCount = 0;

    try {
      if (!serverData.serverItems) {
        if (serverData.fetchError) {
          console.error(`❌ Error syncing server ${this.displayNamePlural}: ${serverData.fetchError}`);
        } else {
          console.warn(`⚠️  Could not retrieve server ${this.displayNamePlural}. Skipping sync.`);
        }
        return { messages, yamlUpdated, orphanedCount };
      }

      const yamlItems = this.getFromYaml(config);
      const { yamlById, yamlByName, serverByName } = this.buildMaps(serverData.serverItems, yamlItems);

      // Part 1: Detect orphaned items
      const orphans = serverData.serverItems.filter((item) => {
        const id = item.id as string;
        const name = item.name as string;
        return !yamlById.has(id) && !yamlByName.has(name) && this.isActive(item) && this.shouldConsiderForOrphan(item);
      });

      if (orphans.length > 0) {
        // Stub server-only primitives into YAML so `lua sync` can classify them
        // as `missing-locally` and resolve them via backup restore.
        const idField = this.yamlConfig.idField;
        const stubs = orphans.map((item) =>
          this.cleanItem({
            name: item.name,
            version: this.getActiveVersion(item) || DEFAULT_VERSION,
            [idField]: item.id || '',
          } as unknown as T)
        );

        yamlItems.push(...stubs);
        yamlUpdated = true;

        const flagName = `--${this.displayName.toLowerCase().replace(/\s+/g, '-')}-name`;
        console.log(`\n⚠️  Found ${this.displayNamePlural} on server not in your local code:`);
        for (const item of orphans) {
          const msg = `   - ${this.getServerItemName(item)}`;
          messages.push(msg);
          console.log(msg);
        }
        console.log(`   Added to lua.skill.yaml as server-only entries.`);
        console.log(`   To remove from server: ${this.deleteCommand} ${flagName} <name>`);
        console.log(`   To restore source from backup: lua sync --accept\n`);
        orphanedCount = orphans.length;
      }

      // Part 2: Sync IDs and versions from server → YAML
      const { items: updatedItems, changed, msgs } = this.syncFromServer(yamlItems, serverByName);
      messages.push(...msgs);

      if (changed) {
        yamlUpdated = true;
        console.log(`✅ YAML ${this.displayNamePlural} synced with server`);
      }

      if (yamlUpdated) {
        this.updateYaml(updatedItems, config);
      }

      // Part 3: Create primitives that don't exist on server (if manifest + credentials provided)
      if (manifest && apiCredentials) {
        const api = this.getApi(apiCredentials.apiKey, apiCredentials.agentId);
        const { created, updated: creationUpdated } = await this.createMissingOnServer(api, manifest);
        if (created.length > 0) {
          messages.push(...created.map((name) => `Created "${name}" on server`));
          yamlUpdated = yamlUpdated || creationUpdated;
        }
      }

      if (orphans.length === 0 && !changed) {
        console.log(`✅ Server ${this.displayNamePlural} and YAML are fully in sync`);
      }
    } catch (error) {
      console.error(`❌ Error syncing server ${this.displayNamePlural}:`, error);
    }

    return { messages, yamlUpdated, orphanedCount };
  }

  async syncWithServer(
    apiKey: string,
    agentId: string,
    config: YamlConfig | null,
    manifest?: CompilationManifest
  ): Promise<SyncResult> {
    const serverData = await this.fetchServerState(apiKey, agentId);
    return this.applySyncToYaml(serverData, config, manifest, { apiKey, agentId });
  }

  // ===========================================================================
  // CREATE ON SERVER
  // ===========================================================================

  /**
   * Create a primitive on the server. Subclasses must implement this.
   * @param api - The API instance
   * @param primitive - The manifest primitive with name, description, and type-specific fields
   * @returns The server-assigned ID for the created primitive, or null on failure.
   */
  protected abstract createOnServer(api: unknown, primitive: ManifestPrimitive): Promise<string | null>;

  /**
   * Create primitives that have empty IDs in YAML.
   * Called internally by syncWithServer when manifest is provided.
   */
  private async createMissingOnServer(
    api: unknown,
    manifest: CompilationManifest
  ): Promise<{ created: string[]; updated: boolean }> {
    const created: string[] = [];
    let updated = false;

    const config = readYamlConfig();
    const items = this.getFromYaml(config);
    const itemsWithoutId = items.filter((item) => !this.getItemId(item));

    if (itemsWithoutId.length === 0) {
      return { created, updated };
    }

    console.log(`\n🔧 Creating ${itemsWithoutId.length} new ${this.displayNamePlural} on server...`);

    for (const item of itemsWithoutId) {
      // Find the primitive in the manifest to get description and other metadata
      const manifestPrimitive = findPrimitive(manifest, item.name, this.kind);
      if (!manifestPrimitive) {
        console.error(`   ❌ "${item.name}" not found in manifest - cannot create`);
        continue;
      }

      try {
        const newId = await this.createOnServer(api, manifestPrimitive);
        if (newId) {
          // Update the item with the new ID
          const updatedConfig = readYamlConfig();
          const updatedItems = this.getFromYaml(updatedConfig);
          const idx = updatedItems.findIndex((i) => i.name === item.name);
          if (idx >= 0) {
            (updatedItems[idx] as Record<string, unknown>)[this.yamlConfig.idField] = newId;
            this.updateYaml(updatedItems, updatedConfig);
            updated = true;
          }
          console.log(`   ✅ Created "${item.name}" (ID: ${newId})`);
          created.push(item.name);
        } else {
          console.error(`   ❌ Failed to create "${item.name}" - no ID returned`);
        }
      } catch (error) {
        console.error(`   ❌ Failed to create "${item.name}": ${error instanceof Error ? error.message : error}`);
      }
    }

    if (created.length > 0) {
      console.log(`✅ Created ${created.length} ${this.displayNamePlural} on server`);
    }

    return { created, updated };
  }

  // ===========================================================================
  // YAML OPERATIONS
  // ===========================================================================

  updateYaml(items: T[], config: YamlConfig | null): void {
    const updatedConfig = {
      ...(config || {}),
      [this.yamlConfig.yamlKey]: items.map((item) => this.cleanItem(item)),
    };
    writeYamlConfig(updatedConfig);
  }

  getFromYaml(config: YamlConfig | null): T[] {
    if (!config) return [];
    const items = config[this.yamlConfig.yamlKey];
    return (Array.isArray(items) ? items : []) as unknown as T[];
  }

  syncYamlWithManifest(manifest: CompilationManifest, config: YamlConfig | null): void {
    const manifestNames = manifest.primitives.filter((p) => p.kind === this.kind).map((p) => p.name);

    if (manifestNames.length === 0) return;

    const existing = this.getFromYaml(config);
    const idField = this.yamlConfig.idField;

    // Keep existing items still in manifest, add new ones
    const kept = existing.filter((item) => manifestNames.includes(item.name)).map((item) => this.cleanItem(item));

    for (const name of manifestNames) {
      if (!kept.some((item) => item.name === name)) {
        kept.push(this.cleanItem({ name, version: DEFAULT_VERSION, [idField]: '' } as T));
      }
    }

    this.updateYaml(kept, config);
  }

  updateVersionInYaml(name: string, newVersion: string, options?: { silent?: boolean }): void {
    try {
      const config = readYamlConfig();
      if (!config) {
        if (options?.silent) return;
        throw new Error('lua.skill.yaml not found');
      }

      const items = this.getFromYaml(config);
      const item = items.find((i) => i.name === name);

      if (!item) {
        if (options?.silent) return;
        throw new Error(`${this.displayName} "${name}" not found in configuration`);
      }

      item.version = newVersion;
      this.updateYaml(items, config);
    } catch (error) {
      if (options?.silent) {
        console.warn(`⚠️  Could not update ${this.displayName} version in YAML:`, error);
        return;
      }
      throw error;
    }
  }

  // ===========================================================================
  // PUSH
  // ===========================================================================

  prepareForPush(
    manifest: CompilationManifest,
    name: string,
    projectPath: string = process.cwd(),
    bundleAccumulator?: Map<string, Buffer>
  ): Record<string, unknown> | null {
    const primitive = findPrimitive(manifest, name, this.kind);
    if (!primitive) return null;

    const code = loadArtifact(primitive, projectPath);

    // BAC-196: when a bundle accumulator is provided, hash the raw gzip and
    // emit `codeS3Hash` instead of inline `code`. The push command will
    // upload all accumulated bundles via presigned PUT before POSTing the
    // version metadata. When no accumulator is provided (legacy callers),
    // fall back to the inline gzip+base64 `code` path.
    if (bundleAccumulator) {
      const rawGzip = compressForPushRaw(code);
      const codeS3Hash = hashBundle(rawGzip);
      bundleAccumulator.set(codeS3Hash, rawGzip);
      return this.buildPushData(primitive, undefined, codeS3Hash);
    }

    const compressedCode = compressForPush(code);
    return this.buildPushData(primitive, compressedCode);
  }

  protected buildPushData(
    primitive: ManifestPrimitive,
    compressedCode: string | undefined,
    codeS3Hash?: string
  ): Record<string, unknown> {
    return {
      name: primitive.name,
      description: primitive.description,
      ...(codeS3Hash ? { codeS3Hash } : { code: compressedCode }),
    };
  }

  /**
   * Push a new version to the server.
   * Each handler implements the type-specific API call.
   */
  abstract pushToServer(
    apiKey: string,
    agentId: string,
    entityId: string,
    pushData: TPushData
  ): Promise<{ success: boolean; error?: string }>;

  /**
   * Deploy/publish a version on the server.
   * Each handler implements the type-specific API call.
   */
  abstract publishVersion(
    apiKey: string,
    agentId: string,
    entityId: string,
    version: string
  ): Promise<{ success: boolean; error?: string }>;

  /**
   * Get the highest version string from the server for conflict avoidance.
   */
  async getHighestServerVersion(apiKey: string, agentId: string, entityId: string): Promise<string | null> {
    // Go through fetchServerState (not fetchFromServer directly) so handler
    // overrides apply — DeviceHandler / DeviceTriggerHandler override
    // fetchServerState to silently degrade on auth/network errors because
    // the Device Gateway is feature-gated. Calling fetchFromServer directly
    // would bypass that override and re-throw auth errors as fatal, blocking
    // `lua push all` entirely for agents without device-gateway access.
    const { serverItems } = await this.fetchServerState(apiKey, agentId);
    if (!serverItems) return null;

    // Find the entity by ID
    const entity = serverItems.find((item: any) => item.id === entityId);
    if (!entity?.versions || !Array.isArray(entity.versions)) return null;

    // Exclude sandbox versions — they live in the same versions[] array
    // as production versions and would otherwise leak into production
    // auto-bump (e.g. `1.0.21-sandbox` → next push tagged `1.0.22-sandbox`).
    const versions: string[] = entity.versions
      .map((v: any) => v.version)
      .filter((v: any): v is string => typeof v === 'string' && !v.includes('-sandbox'));

    if (versions.length === 0) return null;

    return versions.reduce((highest, v) => maxSemver(highest, v), '0.0.0');
  }

  /**
   * Fetch all server items once, extract highest version for each entity ID.
   * More efficient than calling getHighestServerVersion() per entity.
   */
  async batchGetHighestVersions(
    apiKey: string,
    agentId: string,
    entityIds: string[]
  ): Promise<Map<string, string | null>> {
    const result = new Map<string, string | null>();

    // See getHighestServerVersion for the rationale on routing through
    // fetchServerState rather than calling fetchFromServer directly.
    const { serverItems } = await this.fetchServerState(apiKey, agentId);
    if (!serverItems) {
      entityIds.forEach((id) => result.set(id, null));
      return result;
    }

    for (const entityId of entityIds) {
      const entity = serverItems.find((item: any) => item.id === entityId);
      if (!entity?.versions || !Array.isArray(entity.versions)) {
        result.set(entityId, null);
        continue;
      }
      // Exclude sandbox versions — see getHighestServerVersion for rationale.
      const versions: string[] = entity.versions
        .map((v: any) => v.version)
        .filter((v: any): v is string => typeof v === 'string' && !v.includes('-sandbox'));
      result.set(entityId, versions.length > 0 ? versions.reduce((h, v) => maxSemver(h, v), '0.0.0') : null);
    }

    return result;
  }

  // ===========================================================================
  // INTERNAL
  // ===========================================================================

  /** Get the server ID from a YAML item using the configured idField. */
  protected getItemId(item: T): string {
    return ((item as Record<string, unknown>)[this.yamlConfig.idField] as string) || '';
  }

  protected buildMaps(
    serverItems: any[],
    yamlItems: T[]
  ): {
    yamlById: Map<string, T>;
    yamlByName: Map<string, T>;
    serverByName: Map<string, any>;
  } {
    const yamlById = new Map<string, T>();
    const yamlByName = new Map<string, T>();

    for (const item of yamlItems) {
      const id = this.getItemId(item);
      if (id) yamlById.set(id, item);
      yamlByName.set(item.name, item);
    }

    const serverByName = new Map<string, any>();
    for (const item of serverItems) {
      serverByName.set(item.name, item);
    }

    return { yamlById, yamlByName, serverByName };
  }

  /**
   * For each YAML item, match to server by name, populate missing IDs, update versions.
   */
  protected syncFromServer(
    yamlItems: T[],
    serverByName: Map<string, any>
  ): { items: T[]; changed: boolean; msgs: string[] } {
    const msgs: string[] = [];
    let changed = false;
    const idField = this.yamlConfig.idField;

    const items = yamlItems.map((item) => {
      const serverItem = serverByName.get(item.name);
      if (!serverItem) return item;

      let updated = { ...item };

      // Populate missing server ID
      if (!this.getItemId(item) && serverItem.id) {
        const msg = `🔗 Linked "${item.name}" ${this.displayName} to server (ID: ${serverItem.id})`;
        msgs.push(msg);
        console.log(msg);
        changed = true;
        updated = { ...updated, [idField]: serverItem.id };
      }

      // Update version if server has a newer active one
      const versions = serverItem.versions as unknown[];
      if (Array.isArray(versions) && versions.length > 0) {
        const activeVersion = this.getActiveVersion(serverItem);
        const currentVersion = item.version;

        if (activeVersion && activeVersion !== currentVersion) {
          const msg = `📝 Updated "${item.name}" ${this.displayName} version: ${currentVersion} → ${activeVersion}`;
          msgs.push(msg);
          console.log(msg);
          changed = true;
          updated = { ...updated, version: activeVersion };
        }
      }

      return updated;
    });

    return { items, changed, msgs };
  }
}

// =============================================================================
// BASE NON-VERSIONED HANDLER
// =============================================================================

/**
 * Result returned by upsertOnServer. Handlers create-or-update in a single call,
 * so the server-assigned id flows back here.
 */
export interface UpsertResult {
  success: boolean;
  id?: string;
  active?: boolean;
  error?: string;
}

/**
 * Aggregate result of pushing every bundled item in one go.
 */
export interface PushAllResult {
  pushed: string[];
  failed: Array<{ name: string; error: string }>;
  activated: string[];
}

/**
 * For primitives without versions (e.g., MCP servers).
 *
 * Two generic parameters:
 *   T  — shape of items stored in lua.skill.yaml (see yaml.types.ts)
 *   B  — shape of items pushed to the server (bundled from the manifest).
 *        Defaults to T for handlers where the YAML and push payloads match.
 */
export abstract class BaseNonVersionedHandler<
  T extends { name: string },
  B extends { name: string } = T,
> implements PrimitiveHandler<T> {
  abstract readonly kind: PrimitiveKind;
  abstract readonly displayName: string;
  abstract readonly displayNamePlural: string;
  abstract readonly deleteCommand: string;
  abstract readonly yamlConfig: YamlPrimitiveConfig;

  protected abstract getApi(apiKey: string, agentId: string): unknown;
  protected abstract fetchFromServer(api: unknown): Promise<any[] | null>;
  abstract cleanItem(item: T): T;
  protected abstract isActive(item: any): boolean;

  /**
   * Load bundled items from the compilation manifest, ready to push.
   * Each item must have a `name`; other fields are handler-specific.
   */
  abstract loadBundledItems(projectPath?: string): B[];

  /**
   * Create-or-update a single item on the server. Returns the server-assigned
   * id. Implementations SHOULD call persistItemId after a successful upsert
   * so the id is tracked locally from the first push.
   */
  abstract upsertOnServer(apiKey: string, agentId: string, item: B): Promise<UpsertResult>;

  /**
   * Optional hook run after a successful upsert when autoDeploy is set.
   * Default: no-op. Handlers override for post-upsert actions (e.g. MCP
   * activation). Return true if the action fired and succeeded.
   */
  protected async postUpsert(_item: B, _upsert: UpsertResult, _apiKey: string, _agentId: string): Promise<boolean> {
    return false;
  }

  protected getServerItemName(item: any): string {
    return item.name || 'unknown';
  }

  /** Phase 1 of parallel sync: fetch server state (HTTP only, no YAML writes) */
  async fetchServerState(apiKey: string, agentId: string): Promise<ServerSyncData> {
    try {
      const api = this.getApi(apiKey, agentId);
      const serverItems = await this.fetchFromServer(api);
      return { serverItems };
    } catch (error) {
      if (AuthenticationError.isAuthenticationError(error)) throw error;
      return { serverItems: null, fetchError: error instanceof Error ? error.message : String(error) };
    }
  }

  /** Phase 2 of parallel sync: apply fetched data to YAML (orphan detection only for non-versioned) */
  async applySyncToYaml(
    serverData: ServerSyncData,
    config: YamlConfig | null,
    manifest?: CompilationManifest
  ): Promise<SyncResult> {
    const messages: string[] = [];
    let yamlUpdated = false;
    let orphanedCount = 0;

    try {
      if (!serverData.serverItems) {
        if (serverData.fetchError) {
          console.error(`❌ Error syncing server ${this.displayNamePlural}: ${serverData.fetchError}`);
        } else {
          console.warn(`⚠️  Could not retrieve server ${this.displayNamePlural}. Skipping sync.`);
        }
        return { messages, yamlUpdated, orphanedCount };
      }

      const yamlItems = this.getFromYaml(config);
      const idField = this.yamlConfig.idField;

      const getId = (item: T) => ((item as Record<string, unknown>)[idField] as string) || '';
      const yamlById = new Map(yamlItems.filter((i) => getId(i)).map((i) => [getId(i), i]));
      const yamlByName = new Map(yamlItems.map((i) => [i.name, i]));

      // Names present in the current compilation manifest are considered "in local code"
      // even if they haven't been pushed yet (and therefore have no YAML entry).
      // This prevents newly compiled MCP servers from being flagged as orphans.
      const manifestNames = manifest
        ? new Set(getPrimitivesByKind(manifest, this.kind).map((p: any) => p.name as string))
        : new Set<string>();

      const orphans = serverData.serverItems.filter((item) => {
        const id = item.id as string;
        const name = item.name as string;
        return !yamlById.has(id) && !yamlByName.has(name) && !manifestNames.has(name) && this.isActive(item);
      });

      if (orphans.length > 0) {
        // See BaseVersionedHandler.applySyncToYaml for rationale.
        const stubs = orphans.map((item) =>
          this.cleanItem({
            name: item.name,
            [idField]: item.id || '',
          } as unknown as T)
        );
        this.updateYaml([...yamlItems, ...stubs], config);
        yamlUpdated = true;

        const flagName = `--${this.displayName.toLowerCase().replace(/\s+/g, '-')}-name`;
        console.log(`\n⚠️  Found ${this.displayNamePlural} on server not in your local code:`);
        for (const item of orphans) {
          const msg = `   - ${this.getServerItemName(item)}`;
          messages.push(msg);
          console.log(msg);
        }
        console.log(`   Added to lua.skill.yaml as server-only entries.`);
        console.log(`   To remove from server: ${this.deleteCommand} ${flagName} <name>`);
        console.log(`   To restore source from backup: lua sync --accept\n`);
        orphanedCount = orphans.length;
      } else {
        console.log(`✅ Server ${this.displayNamePlural} and YAML are fully in sync`);
      }
    } catch (error) {
      console.error(`❌ Error syncing server ${this.displayNamePlural}:`, error);
    }

    return { messages, yamlUpdated, orphanedCount };
  }

  async syncWithServer(
    apiKey: string,
    agentId: string,
    config: YamlConfig | null,
    manifest?: CompilationManifest
  ): Promise<SyncResult> {
    const serverData = await this.fetchServerState(apiKey, agentId);
    return this.applySyncToYaml(serverData, config, manifest);
  }

  updateYaml(items: T[], config: YamlConfig | null): void {
    const updatedConfig = {
      ...(config || {}),
      [this.yamlConfig.yamlKey]: items.map((item) => this.cleanItem(item)),
    };
    writeYamlConfig(updatedConfig);
  }

  getFromYaml(config: YamlConfig | null): T[] {
    if (!config) return [];
    const items = config[this.yamlConfig.yamlKey];
    return (Array.isArray(items) ? items : []) as unknown as T[];
  }

  prepareForPush(_manifest: CompilationManifest, _name: string, _projectPath?: string): Record<string, unknown> | null {
    return null;
  }

  /**
   * Write a server-assigned id back into lua.skill.yaml for the given item,
   * using the handler's configured idField. Creates a new YAML entry if none
   * exists yet (first-push case).
   */
  persistItemId(name: string, id: string): void {
    const config = readYamlConfig();
    const items = this.getFromYaml(config);
    const idField = this.yamlConfig.idField;
    const existing = items.find((i) => i.name === name);
    if (existing) {
      (existing as Record<string, unknown>)[idField] = id;
    } else {
      items.push({ name, [idField]: id } as unknown as T);
    }
    this.updateYaml(items, config);
  }

  /**
   * Push the given bundled items to the server:
   *   1. Upsert each on the server (create or update by name).
   *   2. persistItemId is expected to run inside upsertOnServer so the
   *      server-assigned id is tracked locally from the first push.
   *   3. When autoDeploy is set, run the postUpsert hook per successfully
   *      pushed item.
   *
   * Caller passes in pre-loaded items (loadBundledItems) so push.ts can
   * decide what to print up front without reading the manifest twice.
   *
   * Error semantics: upsert failures add the item to `failed`; postUpsert
   * failures don't — the push itself already succeeded, only the follow-up
   * step (e.g. activation) failed. Activation errors surface via a warn
   * so they're visible without polluting the failed[] list.
   *
   * Upsert-by-name is idempotent, so a mid-loop crash self-heals on the next
   * run — ids flow back on subsequent calls for anything not yet persisted.
   */
  async pushAll(
    items: B[],
    apiKey: string,
    agentId: string,
    options: { autoDeploy?: boolean } = {}
  ): Promise<PushAllResult> {
    const result: PushAllResult = { pushed: [], failed: [], activated: [] };
    if (items.length === 0) return result;

    for (const item of items) {
      let upsert: UpsertResult;
      try {
        upsert = await this.upsertOnServer(apiKey, agentId, item);
      } catch (error) {
        result.failed.push({
          name: item.name,
          error: error instanceof Error ? error.message : String(error),
        });
        continue;
      }

      if (!upsert.success) {
        result.failed.push({ name: item.name, error: upsert.error || 'unknown error' });
        continue;
      }
      result.pushed.push(item.name);

      if (!options.autoDeploy) continue;

      try {
        const activated = await this.postUpsert(item, upsert, apiKey, agentId);
        if (activated) result.activated.push(item.name);
      } catch (error) {
        // postUpsert failure doesn't invalidate the push — the server has
        // the new config, only the follow-up step failed. Warn for
        // visibility without adding the item to failed[] (which would
        // imply the push itself failed).
        console.warn(
          `⚠️  ${item.name} pushed but post-upsert action failed: ${error instanceof Error ? error.message : String(error)}`
        );
      }
    }

    return result;
  }
}
