import { randomUUID } from 'crypto';
import { ApiResponse } from '../interfaces/common.js';
import { AuthenticationError } from '../errors/auth.error.js';

/**
 * Generic HTTP client with common error handling
 * Provides a base class for all API service classes with standardized HTTP methods
 */
export abstract class HttpClient {
  /**
   * Creates an instance of HttpClient
   * @param baseUrl - The base URL for all API requests
   */
  constructor(protected baseUrl: string) {}

  /**
   * Makes an HTTP request with standardized error handling
   * @param url - The full URL to request
   * @param options - Fetch API request options
   * @returns Promise resolving to an ApiResponse with typed data
   * @private
   */
  private async request<T>(url: string, options: RequestInit = {}): Promise<ApiResponse<T>> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 30000);
    try {
      const response = await fetch(url, {
        ...options,
        signal: controller.signal,
        headers: {
          'Content-Type': 'application/json',
          ...options.headers,
        },
      });

      clearTimeout(timeoutId);

      // Check if response is ok (status 200-299)
      if (!response.ok) {
        // Try to parse error body as JSON. We need the body for 401s too so
        // we can distinguish "API key is bad" from "API key is fine but the
        // user doesn't own this agent" — which produce identical 401 status
        // codes but very different remedies (BAC-202).
        let errorData: Record<string, any>;
        try {
          errorData = (await response.json()) as Record<string, any>;
        } catch (jsonError) {
          errorData = {};
        }

        if (response.status === 401) {
          const serverMessage = typeof errorData.message === 'string' ? errorData.message : undefined;
          // Detect ownership rejections from lua-api's AdminService. The
          // function throws several variants — `User is not an admin`,
          // `…not an admin of the agent`, `…of the organization` — so match
          // the common stem rather than the longer suffixes.
          if (serverMessage && /not an admin/i.test(serverMessage)) {
            throw new AuthenticationError(
              `Access denied for this agent: ${serverMessage}`,
              'no_agent_access',
              serverMessage
            );
          }
          // Standard credential failures: bare NestJS `UnauthorizedException()`
          // (body becomes `{ message: 'Unauthorized' }`), empty/non-JSON
          // bodies, and explicit "invalid/expired/missing token/key" messages
          // from auth.middleware. Use the canonical "your API key may be
          // invalid or expired" message in all of these cases — it's more
          // actionable than echoing "Unauthorized" back to the user, and
          // matches the wrapper's `lua auth configure` hint.
          const isExplicitCredential =
            !!serverMessage && /(invalid|expired|missing|no)\s+(api[\s_-]?key|token|credential)/i.test(serverMessage);
          const isBareAuthRejection = !serverMessage || /^unauthorized$/i.test(serverMessage);
          if (isExplicitCredential || isBareAuthRejection) {
            throw new AuthenticationError(
              'Authentication failed. Your API key may be invalid or expired.',
              'invalid_credentials',
              serverMessage
            );
          }
          // Anything else — e.g. account suspended, billing lapsed, future
          // 401 variants — surface the server message as-is and classify as
          // 'unknown' so we don't misdirect users to `lua auth configure`
          // for a problem that isn't their credentials.
          throw new AuthenticationError(`Authentication failed: ${serverMessage}`, 'unknown', serverMessage);
        }

        if (response.status === 403) {
          const detail = errorData.message || 'You do not have permission to access this resource.';
          throw new Error(
            `Access denied (403): ${detail}\nCheck that your API key has access to this agent/organization.`
          );
        }

        return {
          success: false,
          error: {
            message: errorData.message || `HTTP ${response.status}: ${response.statusText}`,
            statusCode: response.status,
            error: errorData.error,
            ...errorData,
          },
        };
      }

      // Try to parse JSON response
      let data: any;
      try {
        data = await response.json();
      } catch (jsonError) {
        data = {};
      }

      // If the response already has the ApiResponse structure, return it
      if (typeof data === 'object' && data !== null && 'success' in data) {
        return data;
      }

      // Otherwise, wrap the data in a successful ApiResponse
      return {
        success: true,
        data,
      };
    } catch (error) {
      clearTimeout(timeoutId);

      if (AuthenticationError.isAuthenticationError(error)) {
        throw error;
      }

      // 403 errors are thrown as regular Errors — re-throw them (not retryable)
      if (error instanceof Error && error.message.startsWith('Access denied (403)')) {
        throw error;
      }

      // AbortError from timeout — treat as network error (retryable)
      if (error instanceof DOMException && error.name === 'AbortError') {
        return {
          success: false,
          error: {
            message: 'Request timeout (30s)',
            statusCode: 0,
          },
        };
      }

      // Handle network errors, timeouts, etc.
      return {
        success: false,
        error: {
          message: error instanceof Error ? error.message : 'Network request failed',
          statusCode: 0, // Use 0 to indicate network/connection error
        },
      };
    }
  }

  /**
   * Checks if an HTTP status code is retryable
   * @param statusCode - The HTTP status code (0 for network errors)
   * @returns True if the request should be retried
   * @private
   */
  private isRetryableStatus(statusCode: number): boolean {
    // Retry: network errors (0), 429 Too Many Requests, 500-504 server errors
    return statusCode === 0 || statusCode === 429 || (statusCode >= 500 && statusCode <= 504);
  }

  /**
   * Calculates exponential backoff with full jitter (AWS best practice)
   * @param attempt - The retry attempt number (0-based)
   * @param baseMs - Base delay in milliseconds
   * @param maxMs - Maximum delay cap in milliseconds
   * @returns Delay in milliseconds with random jitter
   * @private
   */
  private calculateBackoff(attempt: number, baseMs = 1000, maxMs = 15000): number {
    const exponential = Math.min(maxMs, baseMs * Math.pow(2, attempt));
    return Math.max(100, Math.random() * exponential); // Full jitter, 100ms floor
  }

  /**
   * Wraps request with retry logic for transient failures
   * @param url - The full URL to request
   * @param options - Fetch API request options
   * @param maxRetries - Maximum number of retry attempts (default 3)
   * @returns Promise resolving to an ApiResponse with typed data
   * @private
   */
  private async retryableRequest<T>(url: string, options: RequestInit = {}, maxRetries = 3): Promise<ApiResponse<T>> {
    // Add idempotency key for POST requests
    if (options.method === 'POST') {
      const headers = (options.headers as Record<string, string>) || {};
      if (!headers['X-Idempotency-Key']) {
        headers['X-Idempotency-Key'] = randomUUID();
        options = { ...options, headers: { ...options.headers, ...headers } };
      }
    }

    let lastResult: ApiResponse<T> | null = null;

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        const result = await this.request<T>(url, options);

        // Success or non-retryable error — return immediately
        // If there's no error object, treat as non-retryable (e.g. API returning { success: false } on 200)
        if (result.success || !result.error || !this.isRetryableStatus(result.error.statusCode || 0)) {
          return result;
        }

        lastResult = result;
      } catch (error) {
        // AuthenticationError and 403 errors are thrown, not returned
        // These should NOT be retried — re-throw immediately
        throw error;
      }

      // Wait before retry (but not after the last attempt)
      if (attempt < maxRetries) {
        const backoff = this.calculateBackoff(attempt);
        await new Promise((resolve) => setTimeout(resolve, backoff));
      }
    }

    return lastResult!;
  }

  /**
   * Performs an HTTP GET request
   * @param url - The relative URL path to request (will be appended to baseUrl)
   * @param headers - Optional HTTP headers to include in the request
   * @returns Promise resolving to an ApiResponse with typed data
   * @protected
   */
  protected async httpGet<T>(url: string, headers?: Record<string, string>): Promise<ApiResponse<T>> {
    return this.retryableRequest<T>(this.baseUrl + url, { method: 'GET', headers });
  }

  /**
   * Performs an HTTP POST request
   * @param url - The relative URL path to request (will be appended to baseUrl)
   * @param data - Optional request body data (will be JSON stringified)
   * @param headers - Optional HTTP headers to include in the request
   * @returns Promise resolving to an ApiResponse with typed data
   * @protected
   */
  protected async httpPost<T>(url: string, data?: any, headers?: Record<string, string>): Promise<ApiResponse<T>> {
    return this.retryableRequest<T>(this.baseUrl + url, {
      method: 'POST',
      body: data ? JSON.stringify(data) : undefined,
      headers,
    });
  }

  /**
   * Performs an HTTP PUT request
   * @param url - The relative URL path to request (will be appended to baseUrl)
   * @param data - Optional request body data (will be JSON stringified)
   * @param headers - Optional HTTP headers to include in the request
   * @returns Promise resolving to an ApiResponse with typed data
   * @protected
   */
  protected async httpPut<T>(url: string, data?: any, headers?: Record<string, string>): Promise<ApiResponse<T>> {
    return this.retryableRequest<T>(this.baseUrl + url, {
      method: 'PUT',
      body: data ? JSON.stringify(data) : undefined,
      headers,
    });
  }

  /**
   * Performs an HTTP DELETE request
   * @param url - The relative URL path to request (will be appended to baseUrl)
   * @param headers - Optional HTTP headers to include in the request
   * @returns Promise resolving to an ApiResponse with typed data
   * @protected
   */
  protected async httpDelete<T>(url: string, headers?: Record<string, string>): Promise<ApiResponse<T>> {
    return this.retryableRequest<T>(this.baseUrl + url, { method: 'DELETE', headers });
  }

  /**
   * Performs an HTTP PATCH request
   * @param url - The relative URL path to request (will be appended to baseUrl)
   * @param data - Optional request body data (will be JSON stringified)
   * @param headers - Optional HTTP headers to include in the request
   * @returns Promise resolving to an ApiResponse with typed data
   * @protected
   */
  protected async httpPatch<T>(url: string, data?: any, headers?: Record<string, string>): Promise<ApiResponse<T>> {
    return this.retryableRequest<T>(this.baseUrl + url, {
      method: 'PATCH',
      body: data ? JSON.stringify(data) : undefined,
      headers,
    });
  }
}
