/**
 * AI API — isolated text generation (Vercel AI SDK–aligned); proxied to the API — not the agent chat pipeline.
 * See [`generateText`](https://ai-sdk.dev/docs/reference/ai-sdk-core/generate-text).
 */
export interface AiApi {
  /**
   * Generate text with a user prompt and optional content. Returns plain text.
   *
   * Single-arg: `prompt` is the user prompt.
   * Two-arg: `prompt` is the system instruction, `content` is user message content
   * (AI SDK `UserContent` — a string or array of multimodal parts).
   *
   * @example
   * ```typescript
   * const text = await AI.generate('Summarize the latest AI news.');
   * const text2 = await AI.generate(
   *   'You are a helpful assistant.',
   *   [{ type: 'text', text: 'Hello!' }]
   * );
   * ```
   */
  generate(prompt: string, content?: import('ai').UserContent): Promise<string>;

  /**
   * Generate text with full options — a serializable subset of `generateText`
   * (`model`, `system`, `prompt`, `messages`, `temperature`, `maxOutputTokens`).
   * Returns the full AI SDK–aligned result including `text`, `finishReason`, `usage`,
   * `sources` (Google Search grounding), `reasoning`, `warnings`, and more.
   *
   * @example
   * ```typescript
   * const { text, finishReason, usage, sources } = await AI.generate({
   *   system: 'You are concise.',
   *   prompt: 'Say hi.',
   * });
   * ```
   */
  generate(options: import('@lua/shared-types').AiGenerateInput): Promise<import('@lua/shared-types').AiGenerateOutput>;
}

export const AI: AiApi = {
  async generate(
    promptOrOptions: string | import('@lua/shared-types').AiGenerateInput,
    content?: import('ai').UserContent
  ): Promise<any> {
    const { getAiInstance } = await import('./api/lazy-instances.js');
    const ai = await getAiInstance();
    return ai.generateForSandbox(promptOrOptions, content);
  },
};

