/**
 * Agents API — invoke another agent from inside your skill/tool/job/webhook/
 * processor code.
 */
export interface AgentsApi {
  /**
   * Invoke a target agent with a plain prompt. Returns the assistant's text.
   *
   * @example
   * ```typescript
   * const summary = await Agents.invoke('salesAgent', 'summarize the last order');
   * ```
   */
  invoke(targetAgentId: string, prompt: string): Promise<string>;

  /**
   * Invoke a target agent with full options. Returns the structured
   * {@link AgentInvocationOutput} including `text`, `threadId`, `finishReason`,
   * `usage`, and `toolsUsed`.
   *
   * @example
   * ```typescript
   * const result = await Agents.invoke('salesAgent', {
   *   prompt: 'Draft a reply to the latest order',
   *   threadId: 'order-123',
   *   systemPrompt: 'Be concise.',
   * });
   * console.log(result.text, result.usage);
   * ```
   */
  invoke(
    targetAgentId: string,
    input: import('@lua/shared-types').AgentInvocationInput
  ): Promise<import('@lua/shared-types').AgentInvocationOutput>;
}

export const Agents: AgentsApi = {
  async invoke(
    targetAgentId: string,
    promptOrInput: string | import('@lua/shared-types').AgentInvocationInput
  ): Promise<any> {
    const { getAgentsInstance } = await import('./api/lazy-instances.js');
    const agents = await getAgentsInstance();
    return agents.invokeForSandbox(targetAgentId, promptOrInput);
  },
};

