/**
 * Define a device that an agent can communicate with.
 *
 * Devices support bidirectional communication:
 * - **commands**: Agent → Device (each becomes a tool the agent can call)
 * - **triggers**: Device → Agent (each has an execute handler that runs on the server)
 *
 * @example
 * ```typescript
 * import { defineDevice } from 'lua-cli';
 * import { z } from 'zod';
 *
 * export const printer = defineDevice({
 *   name: 'label-printer',
 *   description: 'Thermal label printer on Raspberry Pi',
 *   group: 'printers',
 *   commands: {
 *     print: {
 *       description: 'Print a label',
 *       inputSchema: z.object({ text: z.string(), copies: z.number().default(1) }),
 *       timeoutMs: 30000,
 *     },
 *   },
 *   triggers: {
 *     paper_low: {
 *       description: 'Fired when paper level drops below threshold',
 *       payloadSchema: z.object({ level: z.number() }),
 *       execute: async (payload, { agent }) => {
 *         await agent.chat(\`Printer paper low: \${payload.level}%\`);
 *       },
 *     },
 *   },
 * });
 * ```
 */
export function defineDevice(config: LuaDeviceConfig): LuaDevice {
  return new LuaDevice(config);
}

/**
 * Define a standalone device trigger primitive.
 *
 * Device triggers represent events fired from a device to an agent.
 * Each trigger is a first-class primitive that is compiled, versioned,
 * and pushed independently.
 *
 * @example
 * ```typescript
 * import { defineDeviceTrigger } from 'lua-cli';
 * import { z } from 'zod';
 *
 * export const paperLow = defineDeviceTrigger({
 *   name: 'paper-low',
 *   description: 'Fired when printer paper drops below threshold',
 *   payloadSchema: z.object({ level: z.number() }),
 *   execute: async (payload, { agent, device }) => {
 *     await agent.chat(\`Printer \${device.name} paper low: \${payload.level}%\`);
 *   },
 * });
 * ```
 */
export function defineDeviceTrigger(config: LuaDeviceTriggerConfig): LuaDeviceTrigger {
  return new LuaDeviceTrigger(config);
}

