/**
 * Compilation Types
 *
 * All types related to the compilation process, plugins, and output manifest.
 * Uses discriminated unions for type-safe primitive handling.
 */

import type { GovernanceConfig, PersonaText, SkillContextText } from '@lua/shared-types';
import type { LuaVoiceModel } from '@lua/shared-types';

// =============================================================================
// COMPILER OPTIONS
// =============================================================================

export interface CompilerOptions {
  /** Root directory of the project */
  rootDir: string;
  /** Output directory for artifacts */
  outDir: string;
  /** Enable source maps */
  sourceMaps?: boolean;
  /** Minify output */
  minify?: boolean;
  /** Enable debug mode (extra verbose logging, preserve temps) */
  debug?: boolean;
  /** Enable verbose output (show each primitive as it compiles) */
  verbose?: boolean;
  /** Skip validation warnings (still show errors) */
  quietWarnings?: boolean;
  /** Add runtime validation wrapper to artifacts (default: true) */
  runtimeValidation?: boolean;
}

// =============================================================================
// COMPILATION RESULT
// =============================================================================

export interface CompilationResult {
  success: boolean;
  manifest: CompilationManifest;
  errors: CompilationError[];
  warnings: CompilationWarning[];
  stats: CompilationStats;
}

/** Base for compilation messages (errors and warnings) */
interface CompilationMessageBase {
  primitive?: string;
  kind?: string;
  file: string;
  line?: number;
  message: string;
}

export interface CompilationError extends CompilationMessageBase {
  column?: number;
  suggestion?: string;
}

export interface CompilationWarning extends CompilationMessageBase {}

export interface CompilationStats {
  totalPrimitives: number;
  byKind: Record<string, number>;
  totalSize: number;
  duration: number;
}

// =============================================================================
// SHARED PRIMITIVE IDENTITY
// =============================================================================

/** Core identity fields shared by all primitive representations */
interface PrimitiveIdentity {
  /** Primitive type (tool, job, webhook, etc.) */
  kind: string;
  /** Name from the definition */
  name: string;
  /** Description from the definition */
  description: string;
  /** Path to the source file */
  sourcePath: string;
}

// =============================================================================
// PATTERN TYPES
// =============================================================================

/**
 * Pattern for primitive authoring shape.
 *
 *   'function'         — `defineX({ ... })`
 *   'class'            — `new LuaX({ ... })` (config-via-instantiation)
 *   'class-definition' — `class MyX extends LuaX { ... }` (subclass-with-field-override)
 */
export type DefinitionPattern = 'class' | 'function' | 'class-definition';

// =============================================================================
// PRIMITIVE METADATA
// =============================================================================

/** Base metadata fields that all primitives share */
export interface BaseMetadataFields {
  pattern?: string;
}

/** Common fields extracted by extractCommonFields() helper (excludes 'kind' which plugins add) */
export interface CommonExtractedFields extends Omit<PrimitiveIdentity, 'kind'> {
  exportName: string;
  isDefaultExport: boolean;
  line: number;
  column: number;
}

/** Metadata extracted from source code during scanning */
export interface PrimitiveMetadata<T extends BaseMetadataFields = BaseMetadataFields> extends PrimitiveIdentity {
  /** The export name in the source file (or 'default' for default exports) */
  exportName: string;
  /** Whether this primitive uses `export default` syntax */
  isDefaultExport: boolean;
  /** Line number in source (for error messages) */
  line?: number;
  /** Column number in source */
  column?: number;
  /** Type-specific metadata (typed per plugin) */
  metadata: T;
}

// =============================================================================
// TYPED METADATA FIELDS (per primitive kind)
// =============================================================================

export interface ToolMetadataFields extends BaseMetadataFields {
  pattern: DefinitionPattern;
  className?: string;
  hasInputSchema: boolean;
  hasCondition?: boolean;
  hasExecute?: boolean;
}

export interface SkillMetadataFields extends BaseMetadataFields {
  pattern: DefinitionPattern;
  /** Tool variable/class names from the source (e.g., ['myTool', 'MyToolClass']) */
  toolRefs: string[];
  /**
   * Absolute source-file path where each tool ref was resolved by the
   * reference resolver, keyed by `className`. Populated when the ref
   * came through the resolver (which follows re-export barrels,
   * wildcard exports, path aliases) so the tool-resolution step can
   * skip a fresh — and simpler — `findImportSource` walk that doesn't
   * traverse those shapes. Absent entries fall back to the legacy
   * single-file import scan.
   *
   * Not emitted to the manifest — consumed by `resolveReferences()`
   * inside the compiler process only.
   */
  toolRefSourcePaths?: Record<string, string>;
  context?: SkillContextText;
}

export interface JobMetadataFields extends BaseMetadataFields {
  pattern: DefinitionPattern;
  scheduleType?: string;
  scheduleExpression?: string;
  scheduleSeconds?: number;
  scheduleExecuteAt?: string;
  scheduleTimezone?: string;
  hasExecute?: boolean;
  hasTimeout?: boolean;
  hasRetry?: boolean;
  timeoutValue?: number;
  retryConfig?: { maxAttempts?: number; backoffSeconds?: number };
}

export interface WebhookMetadataFields extends BaseMetadataFields {
  pattern: DefinitionPattern;
  hasExecute?: boolean;
  hasQuerySchema?: boolean;
  hasHeaderSchema?: boolean;
  hasBodySchema?: boolean;
}

/** Shared metadata for pre/post processors */
export interface ProcessorMetadataFields extends BaseMetadataFields {
  pattern: DefinitionPattern;
  hasExecute?: boolean;
  isAsync?: boolean;
  /** Execution priority (lower runs first; default 100). Read by lua-core's `ProcessorService`. */
  priority?: number;
}

export type PreProcessorMetadataFields = ProcessorMetadataFields;
export type PostProcessorMetadataFields = ProcessorMetadataFields;

export interface MCPServerMetadataFields extends BaseMetadataFields {
  transport: 'stdio' | 'sse' | 'streamable-http';
  url?: string;
  hasUrlResolver?: boolean;
  hasHeadersResolver?: boolean;
  urlResolverSource?: string;
  headersResolverSource?: string;
  command?: string;
  args?: string[];
  env?: Record<string, string>;
  config?: Record<string, unknown>;
}

export interface DeviceTriggerMetadataFields extends BaseMetadataFields {
  pattern: DefinitionPattern;
  hasExecute?: boolean;
  hasPayloadSchema?: boolean;
}

export interface DeviceMetadataFields extends BaseMetadataFields {
  pattern: DefinitionPattern;
  group?: string;
}

export interface VoiceMetadataFields extends BaseMetadataFields {
  pattern: DefinitionPattern;
  /** Normalized discriminated union — `kind: 'inference' | 'plugin'`. */
  llm?: LuaVoiceModel;
  stt?: LuaVoiceModel;
  tts?: LuaVoiceModel;
  vad?: string;
  /** Silero VAD tuning forwarded to `silero.VAD.load(...)` on the worker. */
  vadOptions?: {
    minSpeechDuration?: number;
    minSilenceDuration?: number;
    prefixPaddingDuration?: number;
    activationThreshold?: number;
  };
  turnDetection?: string;
  greeting?: string;
  maxToolSteps?: number;
  userAwayTimeout?: number;
  preemptiveGeneration?: boolean;
  sttLanguage?: string;
  hasInterruption?: boolean;
  hasOnEnter?: boolean;
  hasOnUserTurnCompleted?: boolean;
  hasOnExit?: boolean;
  hasTools?: boolean;
  krispEnabled?: boolean;
  /** Background ambient + thinking sounds. Worker maps clip-name strings to BuiltinAudioClip. */
  backgroundAudio?: { ambient?: unknown; thinking?: unknown };
  /** Output volume 0-100. Applied per-frame in the compiled `ttsNode` override. */
  volume?: number;
  /** Pre-TTS word-boundary text replacements. Case-insensitive. */
  pronunciations?: Record<string, string>;
  /** Persist `session.history` to `Data['call:<sessionId>']` after the call ends. */
  persistTranscript?: boolean;
  /**
   * LiveKit AgentSession `interruption` block. Captured as an object so
   * mode / falseInterruptionTimeout / minDelay / maxDelay actually reach
   * the worker — pre-fix only the boolean `hasInterruption` flag survived
   * the compiler→wire trip and the schema's defaults silently won.
   */
  interruption?: {
    enabled?: boolean;
    mode?: 'adaptive' | 'vad';
    falseInterruptionTimeout?: number;
    resumeFalseInterruption?: boolean;
    minDelay?: number;
    maxDelay?: number;
  };
}

export interface AgentMetadataFields extends BaseMetadataFields {
  /** The agent's persona/system prompt */
  persona: PersonaText;
  /** Static model string (e.g., 'openai/gpt-4o') */
  model?: string;
  /** Whether the model property is a resolver function (bundled inside the artifact) */
  hasModelResolver?: boolean;
  /** Per-agent message batching/debounce configuration */
  batching?: {
    firstMessageDelayMs?: number;
    debounceWindowMs?: number;
    maxBatchMessages?: number;
    serializeProcessing?: boolean;
  };
  /** Governance policy configuration */
  governance?: GovernanceConfig;
  /**
   * Identifiers the agent's `voices` array points at, in order. Resolved
   * to real LuaVoice names at manifest build time using `allPrimitives`.
   */
  voiceRefNames?: string[];
  /**
   * Resolver-discovered source file for each identifier in `voiceRefNames`.
   * Keyed by identifier (the local binding in the agent file). Mirrors
   * `SkillMetadataFields.toolRefSourcePaths` and lets `resolveVoiceRefs`
   * match against the voice primitive's `sourcePath` — necessary when the
   * voice is `export default new LuaVoice(...)`, where the local binding
   * (`mattVoice`) matches neither `exportName` (`default`) nor `name`
   * (`matt-line`). Stripped before persistence (absolute build-machine
   * paths must not land in deliverables — see `sanitizeForPersistence`).
   */
  voiceRefSourcePaths?: Record<string, string>;
}

// =============================================================================
// TYPED METADATA ALIASES
// =============================================================================

export type ToolMetadata = PrimitiveMetadata<ToolMetadataFields>;
export type SkillMetadata = PrimitiveMetadata<SkillMetadataFields>;
export type JobMetadata = PrimitiveMetadata<JobMetadataFields>;
export type WebhookMetadata = PrimitiveMetadata<WebhookMetadataFields>;
export type PreProcessorMetadata = PrimitiveMetadata<PreProcessorMetadataFields>;
export type PostProcessorMetadata = PrimitiveMetadata<PostProcessorMetadataFields>;
export type MCPServerMetadata = PrimitiveMetadata<MCPServerMetadataFields>;
export type DeviceTriggerMetadata = PrimitiveMetadata<DeviceTriggerMetadataFields>;
export type DeviceMetadata = PrimitiveMetadata<DeviceMetadataFields>;
export type AgentMetadata = PrimitiveMetadata<AgentMetadataFields>;
export type VoiceMetadata = PrimitiveMetadata<VoiceMetadataFields>;

// =============================================================================
// VALIDATION
// =============================================================================

export interface ValidationResult {
  valid: boolean;
  errors: ValidationMessage[];
  warnings: ValidationMessage[];
}

export interface ValidationMessage {
  message: string;
  line?: number;
  column?: number;
  suggestion?: string;
  docsUrl?: string;
}

// =============================================================================
// SCHEMAS
// =============================================================================

export interface JSONSchema {
  type?: string | string[];
  properties?: Record<string, JSONSchema>;
  required?: string[];
  items?: JSONSchema;
  enum?: unknown[];
  const?: unknown;
  description?: string;
  default?: unknown;
  minimum?: number;
  maximum?: number;
  minLength?: number;
  maxLength?: number;
  pattern?: string;
  format?: string;
  additionalProperties?: boolean | JSONSchema;
  oneOf?: JSONSchema[];
  anyOf?: JSONSchema[];
  allOf?: JSONSchema[];
  $ref?: string;
}

export interface SchemaSet {
  input?: JSONSchema;
  output?: JSONSchema;
  query?: JSONSchema;
  headers?: JSONSchema;
  body?: JSONSchema;
  [key: string]: JSONSchema | undefined;
}

// =============================================================================
// BUNDLED ARTIFACT
// =============================================================================

export interface BundledArtifact {
  code: string;
  sourceMap: string;
  originalSource: string;
  size: number;
  hash: string;
}

// =============================================================================
// COMPILED PRIMITIVE
// =============================================================================

export interface CompiledPrimitive extends PrimitiveMetadata {
  artifact: BundledArtifact;
  schemas?: SchemaSet;
}

// =============================================================================
// PROJECT FILES
// =============================================================================

export interface ProjectFile {
  /**
   * Path used both as the backup key and the on-disk restore location.
   *
   * For in-project files: path relative to `rootDir` (e.g. `src/index.ts`).
   * For external files (BAC-69): path relative to the workspace root
   *   (e.g. `packages/shared/utils.ts`). These are also marked with
   *   `external: true` so the restore step materializes them under
   *   `.lua/external/<relativePath>` instead of escaping the project dir.
   */
  relativePath: string;
  hash: string;
  size: number;
  type: 'source' | 'config' | 'other';
  /**
   * Set to `true` for files that live outside `rootDir` but inside the
   * containing workspace (monorepo sibling packages). The compiler still
   * backs them up — otherwise `lua init --from-server` can't rebuild the
   * agent — but the restore step treats them specially so the contents
   * don't escape the project directory.
   *
   * Omitted (undefined) for in-project files to keep backup manifests
   * stable for non-monorepo agents.
   */
  external?: boolean;
}

// =============================================================================
// COMPILER CONSTANTS
// =============================================================================

/** Manifest format version. Referenced by entry points, manifests, and minimal manifests. */
export const COMPILER_VERSION = '2.0.0';

/** esbuild compilation target. Referenced by bundler and MCP resolver bundler. */
export const ESBUILD_TARGET = 'node18';

// =============================================================================
// MANIFEST PRIMITIVES
// =============================================================================

export enum PrimitiveKind {
  TOOL = 'tool',
  SKILL = 'skill',
  JOB = 'job',
  WEBHOOK = 'webhook',
  PREPROCESSOR = 'preprocessor',
  POSTPROCESSOR = 'postprocessor',
  MCP_SERVER = 'mcp-server',
  AGENT = 'agent',
  DEVICE = 'device',
  DEVICE_TRIGGER = 'device-trigger',
  VOICE = 'voice',
}

interface ManifestPrimitiveBase extends PrimitiveIdentity {
  /** Path to the compiled artifact */
  path: string;
  /** Content hash for cache invalidation */
  hash: string;
}

export interface ManifestTool extends ManifestPrimitiveBase {
  kind: PrimitiveKind.TOOL;
  schemas?: { input?: JSONSchema; output?: JSONSchema };
  hasCondition?: boolean;
}

export interface ManifestSkill extends ManifestPrimitiveBase {
  kind: PrimitiveKind.SKILL;
  context?: PersonaText;
  tools: string[];
}

export interface ManifestJob extends ManifestPrimitiveBase {
  kind: PrimitiveKind.JOB;
  schedule?: { type: string; expression?: string; seconds?: number; executeAt?: string; timezone?: string };
  timeout?: number;
  retry?: { maxAttempts?: number; backoffSeconds?: number };
  metadata?: Record<string, unknown>;
}

export interface ManifestWebhook extends ManifestPrimitiveBase {
  kind: PrimitiveKind.WEBHOOK;
  schemas?: { query?: JSONSchema; headers?: JSONSchema; body?: JSONSchema };
}

export interface ManifestPreProcessor extends ManifestPrimitiveBase {
  kind: PrimitiveKind.PREPROCESSOR;
  isAsync?: boolean;
  /** Execution priority (lower runs first; default 100). Surfaces source-declared priority on push. */
  priority?: number;
}

export interface ManifestPostProcessor extends ManifestPrimitiveBase {
  kind: PrimitiveKind.POSTPROCESSOR;
  /** Execution priority (lower runs first; default 100). Surfaces source-declared priority on push. */
  priority?: number;
}

export interface ManifestMCPServer extends ManifestPrimitiveBase {
  kind: PrimitiveKind.MCP_SERVER;
  config?: Record<string, unknown>;
  /** Whether the url property is a resolver function (bundled in artifact) */
  hasUrlResolver?: boolean;
  /** Whether the headers property is a resolver function (bundled in artifact) */
  hasHeadersResolver?: boolean;
}

export interface ManifestAgent extends ManifestPrimitiveBase {
  kind: PrimitiveKind.AGENT;
  persona: PersonaText;
  /** Static model string (e.g., 'openai/gpt-4o') */
  model?: string;
  /** Whether the model property is a resolver function (bundled in artifact) */
  hasModelResolver?: boolean;
  /** Per-agent message batching/debounce configuration */
  batching?: {
    firstMessageDelayMs?: number;
    debounceWindowMs?: number;
    maxBatchMessages?: number;
    serializeProcessing?: boolean;
  };
  /** Governance policy configuration */
  governance?: GovernanceConfig;
  /**
   * Voices linked to this agent, in `voices: [...]` order. Each entry is a
   * primitive name; resolved to a server `voiceId` at push time. Each
   * channel picks which one fires via `channelConfig.<kind>.voiceId`.
   */
  voiceRefs?: { name: string }[];
}

export interface ManifestDeviceTrigger extends ManifestPrimitiveBase {
  kind: PrimitiveKind.DEVICE_TRIGGER;
  schemas?: { payload?: JSONSchema };
}

export interface ManifestDevice extends ManifestPrimitiveBase {
  kind: PrimitiveKind.DEVICE;
  group?: string;
}

export interface ManifestVoice extends ManifestPrimitiveBase {
  kind: PrimitiveKind.VOICE;
  /** Normalized discriminated union — Inference (descriptor route) or direct plugin. */
  llm: LuaVoiceModel;
  // Optional for realtime LLMs: full mode skips both, half-cascade keeps only `tts`.
  stt?: LuaVoiceModel;
  tts?: LuaVoiceModel;
  vad?: string;
  /** Silero VAD tuning forwarded to `silero.VAD.load(...)` on the worker. */
  vadOptions?: {
    minSpeechDuration?: number;
    minSilenceDuration?: number;
    prefixPaddingDuration?: number;
    activationThreshold?: number;
  };
  turnDetection?: string;
  greeting?: string;
  maxToolSteps?: number;
  userAwayTimeout?: number;
  preemptiveGeneration?: boolean;
  sttLanguage?: string;
  /** Whether the LuaVoice declares an `interruption` config block. */
  hasInterruption?: boolean;
  /** Presence flags for lifecycle hooks declared on the LuaVoice. */
  hasOnEnter?: boolean;
  hasOnUserTurnCompleted?: boolean;
  hasOnExit?: boolean;
  /** Whether the LuaVoice declares voice-only tools (in addition to skill tools). */
  hasTools?: boolean;
  /** Krisp telephony BVC noise cancellation (opt-in). Resolver flips this on the wire response. */
  krispEnabled?: boolean;
  /** Ambient + thinking sounds. Worker resolves clip-name strings → BuiltinAudioClip. */
  backgroundAudio?: { ambient?: unknown; thinking?: unknown };
  /** Output volume 0-100. Applied per-frame in the compiled `ttsNode` override. */
  volume?: number;
  /** Pre-TTS word-boundary text replacements. Case-insensitive. */
  pronunciations?: Record<string, string>;
  /** When true, the worker writes `session.history` to `Data['call:<sessionId>']` on close. */
  persistTranscript?: boolean;
  /** AgentSession interruption knobs — `mode`, `falseInterruptionTimeout`, etc. */
  interruption?: {
    enabled?: boolean;
    mode?: 'adaptive' | 'vad';
    falseInterruptionTimeout?: number;
    resumeFalseInterruption?: boolean;
    minDelay?: number;
    maxDelay?: number;
  };
}

export type ManifestPrimitive =
  | ManifestTool
  | ManifestSkill
  | ManifestJob
  | ManifestWebhook
  | ManifestPreProcessor
  | ManifestPostProcessor
  | ManifestMCPServer
  | ManifestAgent
  | ManifestDevice
  | ManifestDeviceTrigger
  | ManifestVoice;

// =============================================================================
// COMPILATION MANIFEST
// =============================================================================

export interface CompilationManifest {
  version: string;
  compiledAt: string;
  primitives: ManifestPrimitive[];
  projectFiles: ProjectFile[];
  config: { packageJson?: string; tsconfigJson?: string; luaSkillYaml?: string };
}
