/**
 * Bundle Upload Utilities
 *
 * Handles hashing, existence checking, and S3 presigned upload for primitive code bundles.
 * Enables content-addressed deduplication and delta uploads.
 */

import crypto from 'crypto';
import BackupApi from '../api/backup.api.service.js';
import { BASE_URLS } from '../config/constants.js';

/**
 * Computes SHA256 hash over raw gzipped bytes.
 *
 * @param rawGzip - Raw gzipped bundle bytes (Buffer from compressForPushRaw)
 * @returns SHA256 hex digest
 */
export function hashBundle(rawGzip: Buffer): string {
  return crypto.createHash('sha256').update(rawGzip).digest('hex');
}

/**
 * Telemetry stats returned by `ensureBundlesUploaded` so call sites can
 * report delta-upload hit rate (existed in S3 vs newly uploaded) without
 * having to re-derive the partition.
 */
export interface BundleUploadStats {
  /** Total distinct hashes the push asked about. */
  total: number;
  /** Hashes the server confirmed already existed in S3 (no PUT issued). */
  alreadyExisted: number;
  /** Hashes that required an actual PUT to S3. */
  uploaded: number;
}

/**
 * Ensures all bundles are uploaded to S3 via presigned URLs.
 * Handles the full flow:
 *   1. Call /developer/agents/{agentId}/backup/blob-upload-urls to mint URLs
 *   2. Call /developer/agents/{agentId}/backup/check-blobs to determine missing/existing partition
 *   3. For each missing hash, PUT raw gzip bytes to presigned URL
 *   4. Resolve on success; throw with hash + status on any PUT failure
 *
 * @param apiKey - API key for authentication
 * @param agentId - Agent ID for the presigned URL endpoint
 * @param bundles - Map of hash → raw gzip Buffer bytes
 * @returns Stats covering total / alreadyExisted / uploaded for telemetry
 * @throws Error with hash and status if any PUT fails
 */
export async function ensureBundlesUploaded(
  apiKey: string,
  agentId: string,
  bundles: Map<string, Buffer>
): Promise<BundleUploadStats> {
  // Empty map — nothing to upload
  if (bundles.size === 0) {
    return { total: 0, alreadyExisted: 0, uploaded: 0 };
  }

  const api = new BackupApi(BASE_URLS.API, apiKey, agentId);
  const hashes = Array.from(bundles.keys());

  // Step 1: Get presigned URLs
  const urlResponse = await api.getBlobUploadUrls(hashes);

  if (!urlResponse.success) {
    throw new Error(`Failed to get presigned upload URLs: ${urlResponse.error?.message}`);
  }

  const uploadUrls = urlResponse.data!.urls;

  // Step 2: Check which blobs already exist in S3
  const existsResponse = await api.checkBlobsExist(hashes);

  if (!existsResponse.success) {
    throw new Error(`Failed to check blob existence: ${existsResponse.error?.message}`);
  }

  const missing = existsResponse.data!.missing;

  // Step 3: Upload missing bundles with bounded parallelism via a worker-pool
  // (queue + N workers). Avoids the polling latency of a busy-wait semaphore
  // and stops as soon as the queue is drained.
  const concurrencyLimit = 8;
  const queue = [...missing];

  const uploadOne = async (hash: string): Promise<void> => {
    const url = uploadUrls[hash];
    if (!url) {
      throw new Error(`No presigned URL provided for hash ${hash}`);
    }
    const rawGzip = bundles.get(hash);
    if (!rawGzip) {
      throw new Error(`Bundle buffer not found for hash ${hash}`);
    }
    const response = await fetch(url, {
      method: 'PUT',
      body: rawGzip,
      headers: { 'Content-Type': 'application/octet-stream' },
    });
    if (!response.ok) {
      throw new Error(`S3 PUT failed for hash ${hash}: ${response.status} ${response.statusText}`);
    }
  };

  const workers = Array.from({ length: Math.min(concurrencyLimit, queue.length) }, async () => {
    while (queue.length > 0) {
      const hash = queue.shift();
      if (hash !== undefined) {
        await uploadOne(hash);
      }
    }
  });

  await Promise.all(workers);

  return {
    total: hashes.length,
    alreadyExisted: hashes.length - missing.length,
    uploaded: missing.length,
  };
}
