/**
 * Skill Handler
 *
 * Skills have special behavior:
 * - Custom syncYamlWithManifest (logs success message)
 * - Orphan detection only considers CLI-sourced skills
 * - Uses 'active' field on versions (not 'isActive')
 * - Custom prepareForPush with tools array
 */

import { hasPersonaTextContent } from '@lua/shared-types';
import {
  PrimitiveKind,
  CompilationManifest,
  ManifestPrimitive,
  ManifestSkill,
  ManifestTool,
} from '../compiler/types.js';
import { YamlConfig, YamlConfigSkill } from '../types/yaml.types.js';
import { BASE_URLS } from '../config/constants.js';
import SkillApi from '../api/skills.api.service.js';
import type { PushSkillVersionRequest } from '../interfaces/skills.js';
import { BaseVersionedHandler } from './base.handler.js';
import {
  findPrimitive,
  loadArtifact,
  compressForPush,
  loadOriginalSource,
  normalizeEntryFile,
  buildSourceArchive,
  compressForPushRaw,
  SOURCE_ARCHIVE_SCHEMA_VERSION,
} from '../utils/artifact-loader.js';
import { hashBundle } from '../utils/bundle-upload.js';

import { readYamlConfig, writeYamlConfig } from '../utils/files.js';
import type { YamlPrimitiveConfig, SyncResult } from './types.js';

export class SkillHandler extends BaseVersionedHandler<YamlConfigSkill, PushSkillVersionRequest> {
  readonly kind = PrimitiveKind.SKILL;
  readonly displayName = 'skill';
  readonly displayNamePlural = 'skills';
  readonly deleteCommand = 'lua skills delete';
  readonly yamlConfig: YamlPrimitiveConfig = {
    yamlKey: 'skills',
    idField: 'skillId',
  };

  protected getApi(apiKey: string, agentId: string): SkillApi {
    return new SkillApi(BASE_URLS.API, apiKey, agentId);
  }

  protected async fetchFromServer(api: SkillApi): Promise<any[] | null> {
    const response = await api.getSkills();
    if (!response.success || !response.data?.skills) return null;
    return response.data.skills;
  }

  protected async createOnServer(api: SkillApi, primitive: ManifestPrimitive): Promise<string | null> {
    const skill = primitive as ManifestSkill;
    // Omit context entirely when there's no real content — the API field is
    // optional and @IsPersonaText() rejects empty strings / empty objects to
    // match the SDK push gate. Use the same hasPersonaTextContent predicate
    // so this stays in lockstep with server-side validation.
    const response = await api.createSkill({
      name: skill.name,
      description: skill.description || `A Lua skill for ${skill.name}`,
      ...(hasPersonaTextContent(skill.context) ? { context: skill.context } : {}),
    });
    if (!response.success || !response.data?.id) return null;
    return response.data.id;
  }

  isActive(serverItem: any): boolean {
    return serverItem.active !== false;
  }

  /**
   * Skills use 'active' field on versions (not 'isActive').
   */
  getActiveVersion(serverItem: any): string | null {
    const active = serverItem.versions?.find((v: any) => v.active === true);
    return active?.version ?? null;
  }

  protected shouldConsiderForOrphan(serverItem: any): boolean {
    return serverItem.source === 'cli' || !serverItem.source;
  }

  // ===========================================================================
  // YAML — override to handle legacy single-skill format
  // ===========================================================================

  getFromYaml(config: YamlConfig | null): YamlConfigSkill[] {
    if (!config) return [];

    if (config.skills && Array.isArray(config.skills) && config.skills.length > 0) {
      return config.skills.map((skill) => ({
        name: skill.name || '',
        version: skill.version || '',
        skillId: skill.skillId || '',
      }));
    }

    if (config.skill) {
      const legacy = config.skill;
      return [
        {
          name: legacy.name || 'unnamed-skill',
          version: legacy.version || '',
          skillId: legacy.skillId || '',
        },
      ];
    }

    return [];
  }

  updateVersionInYaml(name: string, newVersion: string, options?: { silent?: boolean }): void {
    try {
      const config = readYamlConfig();
      if (!config) {
        if (options?.silent) return;
        throw new Error('lua.skill.yaml not found');
      }

      let updated = false;

      if (config.skills && Array.isArray(config.skills)) {
        const skill = config.skills.find((s: YamlConfigSkill) => s.name === name);
        if (skill) {
          skill.version = newVersion;
          updated = true;
        }
      }

      if (!updated && config.skill) {
        const legacy = config.skill;
        if (legacy.name === name || name === 'unnamed-skill') {
          legacy.version = newVersion;
          updated = true;
        }
      }

      if (!updated) {
        if (options?.silent) return;
        throw new Error(`Skill "${name}" not found in configuration`);
      }

      writeYamlConfig(config);
    } catch (error) {
      if (options?.silent) {
        console.warn(`⚠️  Could not update skill version in YAML:`, error);
        return;
      }
      throw error;
    }
  }

  syncYamlWithManifest(manifest: CompilationManifest, config: YamlConfig | null): void {
    super.syncYamlWithManifest(manifest, config);
    if (manifest.primitives.some((p) => p.kind === this.kind)) {
      console.log('✅ YAML synced with manifest');
    }
  }

  // ===========================================================================
  // PUSH — custom to include tools array
  // ===========================================================================

  async pushToServer(apiKey: string, agentId: string, entityId: string, pushData: PushSkillVersionRequest) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.pushSkill(entityId, { ...pushData, skillId: entityId });
    return { success: response.success, error: response.error?.message };
  }

  async publishVersion(apiKey: string, agentId: string, entityId: string, version: string) {
    const api = this.getApi(apiKey, agentId);
    const response = await api.publishSkillVersion(entityId, version);
    return { success: response.success, error: response.error?.message };
  }

  prepareForPush(
    manifest: CompilationManifest,
    name: string,
    projectPath: string = process.cwd(),
    bundleAccumulator?: Map<string, Buffer>
  ): Record<string, unknown> | null {
    const skill = findPrimitive<ManifestSkill>(manifest, name, PrimitiveKind.SKILL);
    if (!skill) return null;

    // Track per-tool source so we can also build a skill-level `sourceArchive`
    // alongside the per-tool `source` fields. Both formats are accepted by the
    // canonical-source store; per-tool source unlocks the Builder UI's
    // tool-level edit, the archive unlocks workspace hydration on the
    // conversational Builder side. Shipping both is cheap and matches the
    // server schema (`tools[].source` + `sourceArchive` are both optional).
    const archiveEntries: Array<{ entryFile: string; source: string }> = [];

    const tools = (skill.tools || [])
      .map((toolName: string) => {
        const tool = findPrimitive<ManifestTool>(manifest, toolName, PrimitiveKind.TOOL);
        if (!tool) return null;

        const code = loadArtifact(tool, projectPath);

        let toolData: Record<string, unknown>;

        // BAC-196: when an accumulator is supplied, emit `codeS3Hash` and
        // queue raw gzip for presigned upload. Otherwise use inline path.
        if (bundleAccumulator) {
          const rawGzip = compressForPushRaw(code);
          const codeS3Hash = hashBundle(rawGzip);
          bundleAccumulator.set(codeS3Hash, rawGzip);

          toolData = {
            name: tool.name,
            description: tool.description,
            inputSchema: tool.schemas?.input || undefined,
            codeS3Hash,
          };
          if (tool.hasCondition) {
            // Condition shares the same compiled artifact, so same hash works.
            toolData.condition = codeS3Hash;
          }
        } else {
          const compressedCode = compressForPush(code);
          toolData = {
            name: tool.name,
            description: tool.description,
            inputSchema: tool.schemas?.input || undefined,
            code: compressedCode,
          };
          if (tool.hasCondition) {
            toolData.condition = compressedCode;
          }
        }

        // Attach original TS source. Best-effort: when sourcePath is missing or
        // the file is unreadable, `loadOriginalSource` returns null and we omit
        // both fields. The server treats absent source as "not attached" — same
        // behaviour as older CLI clients that never sent it. Source metadata is
        // independent of bundle delivery mode (inline `code` vs `codeS3Hash`),
        // so it applies to both BAC-196 and inline paths.
        const source = loadOriginalSource(tool.sourcePath, projectPath);
        const entryFile = normalizeEntryFile(tool.sourcePath, projectPath);
        if (source && entryFile) {
          toolData.source = source;
          toolData.entryFile = entryFile;
          archiveEntries.push({ entryFile, source });
        }

        return toolData;
      })
      .filter(Boolean);

    const sourceArchive = buildSourceArchive(archiveEntries);

    return {
      name: skill.name,
      description: skill.description,
      // Same gate as createOnServer — server validator rejects empty content.
      ...(hasPersonaTextContent(skill.context) ? { context: skill.context } : {}),
      tools,
      ...(sourceArchive
        ? {
            sourceArchive,
            archiveSchemaVersion: SOURCE_ARCHIVE_SCHEMA_VERSION,
          }
        : {}),
    };
  }
}

export const skillHandler = new SkillHandler();
