import { Basket, BasketCommon, BasketData, BasketItem, BasketStatus } from '../interfaces/baskets.js';
import { BasketAPI } from '../types/index.js';
import OrderInstance from './order.instance.js';

/**
 * Basket instance class providing a fluent API for managing user baskets
 * Provides methods for adding/removing items, updating metadata, and placing orders
 * Supports direct property access (e.g., basket.items) for accessing data and common properties
 */
export default class BasketInstance {
  private id: string;
  private userId: string;
  private agentId: string;
  private data: BasketData;
  private common: BasketCommon;
  metadata: any;
  totalAmount: string | number;
  itemCount: number;
  status: BasketStatus;
  private basketAPI!: BasketAPI; // Use definite assignment assertion

  // Index signature to allow dynamic property access
  [key: string]: any;

  /**
   * Creates a new BasketInstance with proxy support for direct property access
   * @param api - The BasketAPI instance for making API calls
   * @param basket - The basket data from the API
   * @returns Proxied instance that allows direct access to data and common properties
   */
  constructor(api: BasketAPI, basket: Basket) {
    // Ensure data and common are always objects, never null or undefined
    this.data = basket.data && typeof basket.data === 'object' ? basket.data : ({} as BasketData);
    this.common = basket.common && typeof basket.common === 'object' ? basket.common : ({} as BasketCommon);
    this.id = basket.id;
    this.userId = basket.userId;
    this.agentId = basket.agentId;
    this.metadata = basket.data?.metadata || {};
    this.totalAmount = basket.common?.totalAmount || 0;
    this.itemCount = basket.common?.itemCount || 0;
    this.status = basket.common?.status || BasketStatus.ACTIVE;
    // Make basketAPI non-enumerable so it doesn't show up in console.log
    Object.defineProperty(this, 'basketAPI', {
      value: api,
      writable: true,
      enumerable: false,
      configurable: true,
    });

    // Return a proxy that allows direct property access
    return new Proxy(this, {
      get(target, prop, receiver) {
        // If the property exists on the instance itself, return it
        if (prop in target) {
          return Reflect.get(target, prop, receiver);
        }
        // Check data object (with null check)
        if (typeof prop === 'string' && target.data && typeof target.data === 'object' && prop in target.data) {
          return (target.data as any)[prop];
        }
        // Check common object (with null check)
        if (typeof prop === 'string' && target.common && typeof target.common === 'object' && prop in target.common) {
          return (target.common as any)[prop];
        }
        return undefined;
      },
      set(target, prop, value, receiver) {
        // Reserved properties that should be set on the instance itself
        const reservedProps = [
          'id',
          'userId',
          'agentId',
          'data',
          'common',
          'metadata',
          'totalAmount',
          'itemCount',
          'status',
          'basketAPI',
          'updateMetadata',
          'updateStatus',
          'addItem',
          'removeItem',
          'clear',
          'placeOrder',
          'toJSON',
        ];
        if (typeof prop === 'string' && reservedProps.includes(prop)) {
          return Reflect.set(target, prop, value, receiver);
        }
        // Check if property exists in data or common, otherwise default to data
        if (typeof prop === 'string') {
          // Initialize objects if they don't exist
          if (!target.data || typeof target.data !== 'object') {
            target.data = {} as BasketData;
          }
          if (!target.common || typeof target.common !== 'object') {
            target.common = {} as BasketCommon;
          }
          if (prop in target.common) {
            (target.common as any)[prop] = value;
          } else {
            (target.data as any)[prop] = value;
          }
          return true;
        }
        return false;
      },
      has(target, prop) {
        // Check if property exists on instance, in data, or in common (with null checks)
        if (prop in target) {
          return true;
        }
        if (typeof prop === 'string') {
          if (target.data && typeof target.data === 'object' && prop in target.data) {
            return true;
          }
          if (target.common && typeof target.common === 'object' && prop in target.common) {
            return true;
          }
        }
        return false;
      },
      ownKeys(target) {
        // Return instance keys, data keys, and common keys (with null checks)
        const instanceKeys = Reflect.ownKeys(target);
        const dataKeys = target.data && typeof target.data === 'object' ? Object.keys(target.data) : [];
        const commonKeys = target.common && typeof target.common === 'object' ? Object.keys(target.common) : [];
        return [...new Set([...instanceKeys, ...dataKeys, ...commonKeys])];
      },
      getOwnPropertyDescriptor(target, prop) {
        // First check if it's an instance property
        const instanceDesc = Reflect.getOwnPropertyDescriptor(target, prop);
        if (instanceDesc) {
          return instanceDesc;
        }
        // Then check data properties (with null check)
        if (typeof prop === 'string' && target.data && typeof target.data === 'object' && prop in target.data) {
          return {
            configurable: true,
            enumerable: true,
            writable: true,
            value: (target.data as any)[prop],
          };
        }
        // Then check common properties (with null check)
        if (typeof prop === 'string' && target.common && typeof target.common === 'object' && prop in target.common) {
          return {
            configurable: true,
            enumerable: true,
            writable: true,
            value: (target.common as any)[prop],
          };
        }
        return undefined;
      },
    });
  }

  /**
   * Custom toJSON method to control what gets serialized when logging
   * @returns Serialized basket data combining data and common fields
   */
  toJSON(): Record<string, any> {
    return {
      ...this.data,
      ...this.common,
      id: this.id,
    };
  }

  /**
   * Custom inspect method for Node.js console.log
   * @returns Formatted basket data for console output
   */
  [Symbol.for('nodejs.util.inspect.custom')](): Record<string, any> {
    return {
      ...this.data,
      ...this.common,
      id: this.id,
    };
  }

  /**
   * Updates the basket's metadata
   * @param metadata - The metadata object to merge with existing metadata
   * @returns Promise resolving to the updated basket data
   * @throws Error if the metadata update fails
   */
  async updateMetadata(metadata: any): Promise<any> {
    await this.basketAPI.updateMetadata(this.id, metadata);
    this.data.metadata = { ...this.data.metadata, ...metadata };
    return { ...this.data, ...this.common };
  }

  /**
   * Updates the basket's status
   * @param status - The new basket status to set
   * @returns Promise resolving to the updated basket data
   * @throws Error if the status update fails
   */
  async updateStatus(status: BasketStatus): Promise<any> {
    await this.basketAPI.updateStatus(this.id, status);
    this.common.status = status;
    return { ...this.data, ...this.common };
  }

  /**
   * Updates the basket instance with new data from the API
   * @param basket - The updated basket data from the API
   * @returns The combined basket data and common fields
   * @private
   */
  private updateBasket(basket: Basket): any {
    this.data = basket.data;
    this.common = basket.common;
    this.id = basket.id;
    this.userId = basket.userId;
    this.agentId = basket.agentId;
    this.metadata = basket.data.metadata;
    this.totalAmount = basket.common.totalAmount;
    this.itemCount = basket.common.itemCount;
    this.status = basket.common.status;
    return { ...this.data, ...this.common };
  }

  /**
   * Adds an item to the basket
   * @param item - The basket item to add (must include productId and quantity)
   * @returns Promise resolving to the updated basket data
   * @throws Error if the item cannot be added
   */
  async addItem(item: BasketItem): Promise<any> {
    const basket = await this.basketAPI.addItem(this.id, item);
    return this.updateBasket(basket);
  }

  /**
   * Removes an item from the basket
   * @param itemId - The unique identifier of the item to remove
   * @returns Promise resolving to the updated basket data
   * @throws Error if the item cannot be removed or is not found
   */
  async removeItem(itemId: string): Promise<any> {
    const basket = await this.basketAPI.removeItem(this.id, itemId);
    return this.updateBasket(basket);
  }

  /**
   * Clears all items from the basket
   * @returns Promise resolving to the updated empty basket data
   * @throws Error if the clear operation fails
   */
  async clear(): Promise<any> {
    const basket = await this.basketAPI.clear(this.id);
    return this.updateBasket(basket);
  }

  /**
   * Places an order from the basket contents
   * @param data - Additional order data (shipping info, payment details, etc.)
   * @returns Promise resolving to an OrderInstance representing the created order
   * @throws Error if the order creation fails
   */
  async placeOrder(data: Record<string, any>): Promise<OrderInstance> {
    const order = await this.basketAPI.placeOrder(data, this.id);
    await this.updateStatus(BasketStatus.CHECKED_OUT);
    return order;
  }
}
