/**
 * Analytics Service
 * Non-blocking PostHog telemetry for CLI usage tracking.
 *
 * Opt-out: Set LUA_TELEMETRY=false env var, or run `lua telemetry off`.
 * All tracking is anonymous (hashed API key or machine UUID).
 * Analytics never blocks commands or throws errors to the user.
 */

import { PostHog } from 'posthog-node';
import crypto from 'crypto';
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'fs';
import { platform, release, arch } from 'os';
import { POSTHOG_API_KEY, POSTHOG_HOST, TELEMETRY_FILE, CLI_CONFIG_DIR } from '../config/constants.js';
import { getToken, checkApiKey } from '../services/auth.js';
import { readYamlConfig } from '../utils/files.js';

interface TelemetryConfig {
  enabled: boolean;
  anonymousId: string;
  noticeShown: boolean;
  identifiedApiKeyHash?: string;
  identifiedEmail?: string;
  identifiedName?: string;
}

let client: PostHog | null = null;
let sessionConfig: TelemetryConfig | null = null;
let sessionDistinctId: string | null = null;
let sessionContext: { apiKey?: string; orgId?: string; agentId?: string } = {};

// =============================================================================
// Opt-out Logic
// =============================================================================

function isTelemetryDisabled(): boolean {
  const envVal = process.env.LUA_TELEMETRY;
  if (envVal !== undefined) {
    return ['false', '0', 'off', 'no'].includes(envVal.toLowerCase());
  }

  const config = loadTelemetryConfig();
  return !config.enabled;
}

function loadTelemetryConfig(): TelemetryConfig {
  if (sessionConfig) return sessionConfig;

  try {
    if (existsSync(TELEMETRY_FILE)) {
      sessionConfig = JSON.parse(readFileSync(TELEMETRY_FILE, 'utf8'));
      return sessionConfig!;
    }
  } catch {
    // Corrupt file — regenerate
  }

  sessionConfig = {
    enabled: true,
    anonymousId: crypto.randomUUID(),
    noticeShown: false,
  };
  saveTelemetryConfig(sessionConfig);
  return sessionConfig;
}

function saveTelemetryConfig(config: TelemetryConfig): void {
  try {
    if (!existsSync(CLI_CONFIG_DIR)) {
      mkdirSync(CLI_CONFIG_DIR, { recursive: true });
    }
    writeFileSync(TELEMETRY_FILE, JSON.stringify(config, null, 2), 'utf8');
  } catch {
    // Silently ignore write failures
  }
}

// =============================================================================
// Distinct ID
// =============================================================================

function getDistinctId(apiKey?: string | null): string {
  if (sessionDistinctId && !apiKey) return sessionDistinctId;

  if (apiKey) {
    sessionDistinctId = crypto.createHash('sha256').update(apiKey).digest('hex').substring(0, 16);
  } else {
    const config = loadTelemetryConfig();
    sessionDistinctId = `anon_${config.anonymousId}`;
  }

  return sessionDistinctId;
}

// =============================================================================
// PostHog Client Lifecycle
// =============================================================================

function getClient(): PostHog | null {
  if (isTelemetryDisabled()) return null;

  if (!client) {
    const apiKey = process.env.LUA_POSTHOG_KEY || POSTHOG_API_KEY;
    if (!apiKey) return null;

    client = new PostHog(apiKey, {
      host: POSTHOG_HOST,
      flushAt: 1,
      flushInterval: 0,
    });
  }

  return client;
}

// =============================================================================
// Public API
// =============================================================================

/**
 * Show first-run telemetry notice (once per install).
 */
export function showTelemetryNoticeIfNeeded(): void {
  if (isTelemetryDisabled()) return;

  const config = loadTelemetryConfig();
  if (config.noticeShown) return;

  console.error('');
  console.error('  Lua CLI collects usage data to improve the developer experience.');
  console.error('  To opt out, run: lua telemetry off');
  console.error('  Or set: LUA_TELEMETRY=false');
  console.error('');

  config.noticeShown = true;
  saveTelemetryConfig(config);
}

/**
 * Opportunistically load API key and yaml config to enrich analytics context.
 * Called from withErrorHandling before every command. Never throws.
 */
export async function enrichAnalyticsContext(): Promise<void> {
  if (isTelemetryDisabled()) return;
  try {
    let apiKey: string | null = null;
    try {
      apiKey = getToken();
    } catch {
      /* no key — enrich without identity */
    }
    if (apiKey) {
      // Check if transitioning from anonymous to authenticated
      const previousDistinctId = sessionDistinctId;
      const wasAnonymous = previousDistinctId?.startsWith('anon_');

      sessionContext.apiKey = apiKey;

      // Link anonymous → authenticated identity in PostHog (once per session)
      if (wasAnonymous) {
        const newDistinctId = getDistinctId(apiKey);
        const ph = getClient();
        if (ph && previousDistinctId) {
          ph.alias({ distinctId: newDistinctId, alias: previousDistinctId });
        }
      }

      // Identify user in PostHog with person properties (cached to avoid network call)
      const currentHash = getDistinctId(apiKey);
      const telemetryConfig = loadTelemetryConfig();

      if (telemetryConfig.identifiedApiKeyHash === currentHash) {
        // Cached — identify with stored data (no network call)
        const ph = getClient();
        if (ph) {
          ph.identify({
            distinctId: currentHash,
            properties: {
              email: telemetryConfig.identifiedEmail || null,
              name: telemetryConfig.identifiedName || null,
              os: platform(),
            },
          });
        }
      } else {
        // New API key or first time — fetch user data and cache
        try {
          const userData = await checkApiKey(apiKey);
          if (userData) {
            telemetryConfig.identifiedApiKeyHash = currentHash;
            telemetryConfig.identifiedEmail = userData.email;
            telemetryConfig.identifiedName = userData.fullName;
            saveTelemetryConfig(telemetryConfig);

            const ph = getClient();
            if (ph) {
              ph.identify({
                distinctId: currentHash,
                properties: {
                  email: userData.email || null,
                  name: userData.fullName || null,
                  os: platform(),
                },
              });
            }
          }
        } catch {
          // Best-effort — don't block commands
        }
      }
    }

    const config = readYamlConfig();
    if (config?.agent?.agentId) {
      sessionContext.agentId = config.agent.agentId;
    }
    if (config?.agent?.orgId) {
      sessionContext.orgId = config.agent.orgId;
    }
  } catch {
    // Best-effort — never block the command
  }
}

/**
 * Track a command execution event. Fire-and-forget, never throws.
 */
export function trackCommand(params: {
  commandName: string;
  success: boolean;
  durationMs: number;
  cliVersion: string;
  error?: string;
  properties?: Record<string, any>;
}): void {
  try {
    const ph = getClient();
    if (!ph) return;

    const distinctId = getDistinctId(sessionContext.apiKey);

    ph.capture({
      distinctId,
      event: 'cli_command_executed',
      properties: {
        command: params.commandName,
        success: params.success,
        duration_ms: params.durationMs,
        cli_version: params.cliVersion,
        error_message: params.error?.substring(0, 200) || null,
        os: platform(),
        os_version: release(),
        arch: arch(),
        node_version: process.version,
        ci_mode: !!process.env.CI || !process.stdin.isTTY,
        org_id: sessionContext.orgId || null,
        agent_id: sessionContext.agentId || null,
        ...params.properties,
      },
    });
  } catch {
    // Never throw from analytics
  }
}

/**
 * Track a specific named event with properties. Fire-and-forget, never throws.
 * Use for per-command events (e.g., 'cli_push_completed', 'cli_compile_completed').
 * Auto-enriched with distinct ID, OS, CLI version, and session context.
 */
export function trackEvent(eventName: string, properties?: Record<string, any>): void {
  try {
    const ph = getClient();
    if (!ph) return;

    const distinctId = getDistinctId(sessionContext.apiKey);

    ph.capture({
      distinctId,
      event: eventName,
      properties: {
        os: platform(),
        os_version: release(),
        arch: arch(),
        node_version: process.version,
        ci_mode: !!process.env.CI || !process.stdin.isTTY,
        org_id: sessionContext.orgId || null,
        agent_id: sessionContext.agentId || null,
        ...properties,
      },
    });
  } catch {
    // Never throw from analytics
  }
}

/**
 * Set telemetry enabled/disabled and persist.
 */
export function setTelemetryEnabled(enabled: boolean): void {
  const config = loadTelemetryConfig();
  config.enabled = enabled;
  saveTelemetryConfig(config);
}

/**
 * Get current telemetry status.
 */
export function getTelemetryStatus(): { enabled: boolean; envOverride: boolean } {
  const envVal = process.env.LUA_TELEMETRY;
  const envOverride = envVal !== undefined;
  return {
    enabled: !isTelemetryDisabled(),
    envOverride,
  };
}

/**
 * Clears cached identity data from telemetry.json.
 * Called during re-authentication to ensure stale user data
 * is not carried over from a previous account.
 */
export function clearIdentityCache(): void {
  try {
    const config = loadTelemetryConfig();
    delete config.identifiedApiKeyHash;
    delete config.identifiedEmail;
    delete config.identifiedName;
    saveTelemetryConfig(config);
    // Also clear the in-memory session cache so enrichAnalyticsContext re-fetches
    sessionDistinctId = null;
  } catch {
    // Best-effort — never block auth flows
  }
}

/**
 * Gracefully shutdown PostHog client.
 * Has a 1-second hard timeout to prevent blocking exit.
 */
export async function shutdownAnalytics(): Promise<void> {
  if (!client) return;

  try {
    await Promise.race([client.shutdown(), new Promise((resolve) => setTimeout(resolve, 1000).unref())]);
  } catch {
    // Silently ignore shutdown errors
  } finally {
    client = null;
  }
}
