import { HttpClient } from './http.client.js';
import UserDataInstance from '../instances/user.instance.js';
import { ApiResponse } from '../interfaces/common.js';
import { Message } from '../interfaces/message.js';
import { UserDataAPI } from '../types/index.js';
import { ChatHistoryMessage } from '../interfaces/chat.js';
import {
  UserLookupOptions,
  ProfileResponse,
  UserDataResponse,
  AdminUserResponse,
  SendMessageResponse,
} from '../interfaces/user.js';
import { getDeveloperInstance } from './lazy-instances.js';

// User Data API calls
export default class UserDataApi extends HttpClient implements UserDataAPI {
  private apiKey: string;
  private agentId: string;

  /**
   * Creates an instance of UserDataApi
   * @param baseUrl - The base URL for the API
   * @param apiKey - The API key for authentication
   * @param agentId - The unique identifier of the agent
   */
  constructor(baseUrl: string, apiKey: string, agentId: string) {
    super(baseUrl);
    this.apiKey = apiKey;
    this.agentId = agentId;
  }

  /**
   * Retrieves user data by userId, email, or phone.
   * @param identifier - Optional userId string or lookup options object
   * @returns Promise resolving to a UserDataInstance, or null if not found (for email/phone lookup)
   * @throws Error if the user data cannot be retrieved or the request fails
   */
  async get(identifier?: string | UserLookupOptions): Promise<UserDataInstance | null> {
    let userId: string | undefined;

    // Handle object-based lookup (email or phone)
    if (identifier && typeof identifier === 'object') {
      const profile = await this.resolveUserProfile(identifier);
      if (!profile) return null;
      userId = profile.id;
    } else {
      userId = identifier;
    }

    let url = `/developer/user/data/agent/${this.agentId}`;
    if (userId) {
      url += `/user/${userId}`;
    }
    const response = await this.httpGet<UserDataResponse>(url, {
      Authorization: `Bearer ${this.apiKey}`,
    });
    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to get user data');
    }

    // Extract profile data and remove from response
    const profile = response.data?._luaProfile;
    const { _luaProfile, ...data } = response.data || {};

    return new UserDataInstance(this, data, profile);
  }

  /**
   * Resolves email or phone to user profile via DeveloperApi
   * @param options - Lookup options containing email or phone
   * @returns Promise resolving to ProfileResponse or null if not found
   */
  private async resolveUserProfile(options: UserLookupOptions): Promise<ProfileResponse | null> {
    try {
      const developerApi = await getDeveloperInstance();

      if (options.email) {
        const response = await developerApi.getUserProfileByEmail(options.email);
        return response.success ? (response.data ?? null) : null;
      }
      if (options.phone) {
        const response = await developerApi.getUserProfileByPhone(options.phone);
        return response.success ? (response.data ?? null) : null;
      }
    } catch (error: any) {
      // Return null for 404, rethrow other errors
      if (error.message?.includes('404') || error.message?.includes('not found')) {
        return null;
      }
      throw error;
    }
    return null;
  }

  /**
   * Updates the current user's data for the specific agent
   * @param data - The data object containing fields to update or add to user data
   * @returns Promise resolving to the updated user data
   * @throws Error if the update fails or the request is unsuccessful
   */
  async update(data: Record<string, any>): Promise<Record<string, any>> {
    const response = await this.httpPut<UserDataResponse>(`/developer/user/data/agent/${this.agentId}`, data, {
      Authorization: `Bearer ${this.apiKey}`,
    });
    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to update user data');
    }

    // Extract profile if present and remove from response
    const { _luaProfile, ...cleanData } = response.data || {};

    return cleanData;
  }

  /**
   * Clears all user data for the current user and specific agent
   * @returns Promise resolving to an empty object upon successful deletion
   * @throws Error if the clear operation fails or the request is unsuccessful
   */
  async clear(): Promise<Record<string, never>> {
    const response = await this.httpDelete<{ success: boolean }>(`/developer/user/data/agent/${this.agentId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to clear user data');
    }
    return {};
  }

  /**
   * Sends a message to a specific user conversation for the agent
   * @param messages - An array of messages to send (can be text, image, or file types)
   * @returns Promise resolving to the response data from the server
   * @throws Error if the message sending fails or the request is unsuccessful
   */
  async sendMessage(messages: Message[]): Promise<SendMessageResponse> {
    const user = await this.getAdminUser();
    const response = await this.httpPost<SendMessageResponse>(
      `/admin/agents/${this.agentId}/conversations/${user.uid}`,
      { messages },
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to send message');
    }
    return response.data!;
  }

  /**
   * Gets the admin user for the specific agent
   * @returns Promise resolving to the admin user data
   * @throws Error if the admin user cannot be retrieved or the request is unsuccessful
   */
  async getAdminUser(): Promise<AdminUserResponse> {
    const response = await this.httpGet<AdminUserResponse>(`/admin`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to get admin user');
    }
    return response.data!;
  }

  /**
   * Gets the chat history for the current user and agent
   * @returns Promise resolving to an array of chat messages
   * @throws Error if the chat history cannot be retrieved or the request is unsuccessful
   *
   * @example
   * ```typescript
   * const history = await User.getChatHistory();
   * // Returns: [{ role: 'user', content: [...], createdAt: '...' }, ...]
   * ```
   */
  async getChatHistory(): Promise<ChatHistoryMessage[]> {
    const response = await this.httpGet<ChatHistoryMessage[]>(`/chat/history/${this.agentId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
    if (!response.success) {
      throw new Error(response.error?.message || 'Failed to get chat history');
    }
    return response.data || [];
  }
}
