/**
 * Artifact Loader Utilities
 *
 * Utilities for loading compilation artifacts from the new compiler output (dist-v2/).
 * Used by push, test, and dev commands.
 */

import fs from 'fs';
import path from 'path';
import zlib from 'zlib';
import type { PersonaText } from '@lua/shared-types';
import type { CompilationManifest, ManifestPrimitive, ManifestAgent } from '../compiler/types.js';
import { PrimitiveKind } from '../compiler/types.js';
import { COMPILE_DIRS, COMPILE_FILES } from '../config/compile.constants.js';

// =============================================================================
// MANIFEST LOADING
// =============================================================================

/**
 * Load the compilation manifest from dist-v2/manifest.json.
 *
 * @param projectPath - Path to the project root (defaults to cwd)
 * @returns The compilation manifest
 * @throws Error if manifest not found or invalid
 */
export function loadManifest(projectPath: string = process.cwd()): CompilationManifest {
  const manifestPath = path.join(projectPath, COMPILE_DIRS.DIST_V2, COMPILE_FILES.MANIFEST_JSON);

  if (!fs.existsSync(manifestPath)) {
    throw new Error(
      `Manifest not found at ${manifestPath}. ` + `Run "lua compile" first to generate the compilation output.`
    );
  }

  try {
    const content = fs.readFileSync(manifestPath, 'utf-8');
    return JSON.parse(content);
  } catch (error: any) {
    throw new Error(`Failed to parse manifest: ${error.message}`);
  }
}

/**
 * Check if the compilation output exists.
 *
 * @param projectPath - Path to the project root
 * @returns true if dist-v2/manifest.json exists
 */
export function hasCompilationOutput(projectPath: string = process.cwd()): boolean {
  const manifestPath = path.join(projectPath, COMPILE_DIRS.DIST_V2, COMPILE_FILES.MANIFEST_JSON);
  return fs.existsSync(manifestPath);
}

// =============================================================================
// ARTIFACT LOADING
// =============================================================================

/**
 * Load a primitive artifact (bundled JS code) from disk.
 *
 * @param primitive - The primitive from the manifest
 * @param projectPath - Path to the project root
 * @returns The artifact code as a string
 */
export function loadArtifact(primitive: ManifestPrimitive, projectPath: string = process.cwd()): string {
  const artifactPath = path.join(projectPath, COMPILE_DIRS.DIST_V2, primitive.path);

  if (!fs.existsSync(artifactPath)) {
    throw new Error(`Artifact not found: ${artifactPath}`);
  }

  return fs.readFileSync(artifactPath, 'utf-8');
}

/**
 * Load a primitive artifact and its metadata JSON.
 *
 * @param primitive - The primitive from the manifest
 * @param projectPath - Path to the project root
 * @returns Object with code and metadata
 */
export function loadArtifactWithMetadata(
  primitive: ManifestPrimitive,
  projectPath: string = process.cwd()
): { code: string; metadata: Record<string, any> } {
  const code = loadArtifact(primitive, projectPath);

  // Load metadata JSON (same name but .json extension)
  const metadataPath = path.join(
    projectPath,
    COMPILE_DIRS.DIST_V2,
    path.join(path.dirname(primitive.path), path.basename(primitive.path, '.js') + '.json')
  );

  let metadata = {};
  if (fs.existsSync(metadataPath)) {
    metadata = JSON.parse(fs.readFileSync(metadataPath, 'utf-8'));
  }

  return { code, metadata };
}

/**
 * Load source map for a primitive (if it exists).
 *
 * @param primitive - The primitive from the manifest
 * @param projectPath - Path to the project root
 * @returns The source map string or null if not found
 */
export function loadSourceMap(primitive: ManifestPrimitive, projectPath: string = process.cwd()): string | null {
  const sourceMapPath = path.join(projectPath, COMPILE_DIRS.DIST_V2, primitive.path + '.map');

  if (!fs.existsSync(sourceMapPath)) {
    return null;
  }

  return fs.readFileSync(sourceMapPath, 'utf-8');
}

// =============================================================================
// COMPRESSION (for push)
// =============================================================================

/**
 * Compress code for pushing to server.
 * Uses gzip + base64 encoding (matches server expectation).
 *
 * @param code - The artifact code to compress
 * @returns Base64-encoded gzipped code
 */
export function compressForPush(code: string): string {
  const compressed = zlib.gzipSync(Buffer.from(code, 'utf-8'));
  return compressed.toString('base64');
}

/**
 * Compress code for presigned S3 upload.
 * Returns raw gzip bytes (no base64 encoding).
 * Used with hashBundle and ensureBundlesUploaded for content-addressed upload.
 *
 * @param code - The artifact code to compress
 * @returns Raw gzipped bytes as Buffer
 */
export function compressForPushRaw(code: string): Buffer {
  return zlib.gzipSync(Buffer.from(code, 'utf-8'));
}

/**
 * Decompress code from server format.
 *
 * @param compressed - Base64-encoded gzipped code
 * @returns The decompressed code
 */
export function decompressFromServer(compressed: string): string {
  const buffer = Buffer.from(compressed, 'base64');
  const decompressed = zlib.gunzipSync(buffer);
  return decompressed.toString('utf-8');
}

// =============================================================================
// SOURCE TS LOADING (for canonical-source attach)
// =============================================================================

/**
 * Forward-compat marker for the source-archive layout. Must stay in lockstep
 * with `ARCHIVE_SCHEMA_VERSION` in lua-claude-builder's
 * `canonical-source.archive.ts` — that constant is what the Builder reads when
 * deciding whether it understands an archive.
 */
export const SOURCE_ARCHIVE_SCHEMA_VERSION = 1;

/** Maximum byte size of an individual file we'll archive — protects against accidentally archiving large blobs. Matches the Builder's MAX_FILE_BYTES guard. */
const MAX_SOURCE_FILE_BYTES = 256 * 1024;

/**
 * Read a tool's original TS source file from disk, given its `sourcePath`
 * field on the manifest entry. Returns `null` when the file is missing or
 * unreadable so the caller can omit `tools[].source` rather than fail the
 * whole push — the server already treats absent source as "not attached"
 * (back-compat with older CLI clients).
 */
export function loadOriginalSource(sourcePath: string | undefined, projectPath: string = process.cwd()): string | null {
  if (!sourcePath) return null;
  try {
    const abs = path.isAbsolute(sourcePath) ? sourcePath : path.join(projectPath, sourcePath);
    if (!fs.existsSync(abs)) return null;
    const size = fs.statSync(abs).size;
    if (size > MAX_SOURCE_FILE_BYTES) return null;
    return fs.readFileSync(abs, 'utf-8');
  } catch {
    return null;
  }
}

/**
 * Normalize a tool's `sourcePath` into a relative-to-project, posix-style key
 * suitable for a `sourceArchive` map. Idempotent for already-relative paths;
 * falls back to the bare `sourcePath` if normalization can't make it relative
 * (e.g. on a different drive on Windows). The archive consumer
 * (`canonical-source.archive.writeArchiveToWorkspace`) rejects any key
 * containing `..`, so we strip those defensively.
 */
export function normalizeEntryFile(sourcePath: string | undefined, projectPath: string = process.cwd()): string | null {
  if (!sourcePath) return null;
  let rel: string;
  if (path.isAbsolute(sourcePath)) {
    rel = path.relative(projectPath, sourcePath);
  } else {
    rel = sourcePath;
  }
  if (rel.startsWith('..') || rel.includes(`..${path.sep}`)) return null;
  return rel.split(path.sep).join('/');
}

/**
 * Build a sourceArchive payload (gzip(JSON.stringify({relPath: contents})) →
 * base64) from a list of `{ entryFile, source }` pairs. Format matches
 * `canonical-source.archive.decodeWorkspaceArchive` on the Builder side.
 *
 * Returns `null` when the file map is empty so the caller can omit the
 * `sourceArchive` field entirely (vs. shipping an archive that decodes to an
 * empty workspace, which the Builder treats identically but adds payload
 * weight for nothing).
 */
export function buildSourceArchive(files: Array<{ entryFile: string; source: string }>): string | null {
  if (files.length === 0) return null;
  const map: Record<string, string> = {};
  for (const { entryFile, source } of files) {
    if (entryFile.includes('..')) continue;
    map[entryFile] = source;
  }
  if (Object.keys(map).length === 0) return null;
  const json = JSON.stringify(map);
  const gz = zlib.gzipSync(Buffer.from(json, 'utf-8'));
  return gz.toString('base64');
}

// =============================================================================
// PRIMITIVE FILTERING
// =============================================================================

/**
 * Get primitives of a specific kind from the manifest.
 *
 * @param manifest - The compilation manifest
 * @param kind - The primitive kind to filter by
 * @returns Array of primitives matching the kind
 */
export function getPrimitivesByKind<T extends ManifestPrimitive>(
  manifest: CompilationManifest,
  kind: PrimitiveKind
): T[] {
  return manifest.primitives.filter((p) => p.kind === kind) as T[];
}

/**
 * Find a primitive by name and kind.
 *
 * @param manifest - The compilation manifest
 * @param name - The primitive name
 * @param kind - Optional kind to filter by
 * @returns The primitive or undefined
 */
export function findPrimitive<T extends ManifestPrimitive>(
  manifest: CompilationManifest,
  name: string,
  kind?: T['kind']
): T | undefined {
  return manifest.primitives.find((p) => {
    if (kind && p.kind !== kind) return false;
    return p.name === name;
  }) as T | undefined;
}

// =============================================================================
// SINGLE PRIMITIVE LOOKUP
// =============================================================================

/**
 * Find the first primitive of a given kind from the manifest.
 * Generic version — works for any primitive kind.
 */
export function getFirstPrimitiveByKind<T extends ManifestPrimitive>(
  kind: PrimitiveKind,
  projectPath: string = process.cwd()
): T | null {
  if (!hasCompilationOutput(projectPath)) return null;
  const manifest = loadManifest(projectPath);
  return (manifest.primitives.find((p) => p.kind === kind) as T) ?? null;
}

// =============================================================================
// AGENT CONVENIENCE (delegates to generic lookup)
// =============================================================================

export function getAgentName(projectPath: string = process.cwd()): string | null {
  return getFirstPrimitiveByKind<ManifestAgent>(PrimitiveKind.AGENT, projectPath)?.name ?? null;
}

export function getAgentPersona(projectPath: string = process.cwd()): PersonaText | null {
  return getFirstPrimitiveByKind<ManifestAgent>(PrimitiveKind.AGENT, projectPath)?.persona ?? null;
}

export function getAgentModel(projectPath: string = process.cwd()): string | null {
  return getFirstPrimitiveByKind<ManifestAgent>(PrimitiveKind.AGENT, projectPath)?.model ?? null;
}

export function getAgentGovernance(projectPath: string = process.cwd()): ManifestAgent['governance'] | null {
  return getFirstPrimitiveByKind<ManifestAgent>(PrimitiveKind.AGENT, projectPath)?.governance ?? null;
}

// =============================================================================
// BATCH LOADING
// =============================================================================

/**
 * Load all artifacts of a specific kind.
 *
 * @param manifest - The compilation manifest
 * @param kind - The primitive kind
 * @param projectPath - Path to the project root
 * @returns Array of { primitive, code } objects
 */
export function loadAllArtifactsOfKind(
  manifest: CompilationManifest,
  kind: PrimitiveKind,
  projectPath: string = process.cwd()
): Array<{ primitive: ManifestPrimitive; code: string }> {
  return getPrimitivesByKind(manifest, kind).map((primitive) => ({
    primitive,
    code: loadArtifact(primitive, projectPath),
  }));
}
