/**
 * Authentication Service
 * Handles all authentication operations including API key management and OTP flows
 */

import 'dotenv/config';
import { readFileSync, writeFileSync, mkdirSync, unlinkSync } from 'fs';
import { dirname } from 'path';
import { UserData } from '../interfaces/admin.js';
import AuthApi from '../api/auth.api.service.js';
import { BASE_URLS, CREDENTIALS_FILE } from '../config/constants.js';
import { AuthenticationError } from '../errors/auth.error.js';

// ============================================================================
// TOKEN RESOLUTION
// ============================================================================

/**
 * Retrieves the API key from the following sources in priority order:
 * 1. LUA_API_KEY environment variable (CI/CD, Docker, manual export)
 *    — this also covers .env files, since dotenv/config (imported above)
 *    loads them into process.env before this function is called.
 * 2. ~/.lua-cli/credentials file (written by `lua auth configure`)
 *
 * Throws AuthenticationError with clear instructions if no key is found.
 */
export function getToken(): string {
  // Priority 1: Environment variable (also catches .env values loaded by dotenv)
  if (process.env.LUA_API_KEY) {
    return process.env.LUA_API_KEY;
  }

  // Priority 2: Credentials file (written by `lua auth configure`)
  try {
    const token = readFileSync(CREDENTIALS_FILE, 'utf8').trim();
    if (token) return token;
  } catch {
    // File doesn't exist or is not readable — fall through to error
  }

  // Embed full remediation in the message and tell withErrorHandling not to
  // append its generic credential hint — the three options below are richer
  // than the wrapper's default for this specific case (no key at all).
  throw new AuthenticationError(
    'No API key found.\n' +
      '\n' +
      '  Authenticate using one of these methods:\n' +
      '\n' +
      '    ➜  lua auth configure\n' +
      '    ➜  export LUA_API_KEY="your-api-key-here"\n' +
      '    ➜  Add LUA_API_KEY=... to a .env file\n' +
      '\n' +
      '  🔑 Get your API key at https://admin.heylua.ai',
    'invalid_credentials',
    undefined,
    true
  );
}

/**
 * Returns the API key if present, or null if missing — never throws.
 *
 * Mirrors {@link getToken}'s priority order (env var, then credentials file)
 * but is safe to call from diagnostic / "doctor" code paths where authentication
 * is optional (e.g. `lua status`).
 */
export function loadApiKey(): string | null {
  if (process.env.LUA_API_KEY) {
    return process.env.LUA_API_KEY;
  }
  try {
    const token = readFileSync(CREDENTIALS_FILE, 'utf8').trim();
    return token || null;
  } catch {
    return null;
  }
}

// ============================================================================
// CREDENTIALS FILE OPERATIONS (Local Storage)
// ============================================================================

/**
 * Saves API key to ~/.lua-cli/credentials with owner-only permissions (0600).
 * Called by `lua auth configure` after successful server validation.
 *
 * @param apiKey - The API key to store
 */
export function saveApiKey(apiKey: string): void {
  mkdirSync(dirname(CREDENTIALS_FILE), { recursive: true });
  writeFileSync(CREDENTIALS_FILE, apiKey, { mode: 0o600 });
}

/**
 * Deletes the credentials file.
 * Called by `lua auth logout`.
 *
 * @returns true if deleted successfully, false if not found or deletion failed
 */
export function deleteApiKey(): boolean {
  try {
    unlinkSync(CREDENTIALS_FILE);
    return true;
  } catch {
    return false;
  }
}

// ============================================================================
// API OPERATIONS (Server Authentication)
// ============================================================================

/**
 * Validates an API key with the server and retrieves user data.
 *
 * @param apiKey - The API key to validate
 * @returns Promise resolving to user data including admin info and organizations
 * @throws AuthenticationError if the API key is invalid
 */
export async function checkApiKey(apiKey: string): Promise<UserData> {
  const authApi = new AuthApi(BASE_URLS.API);
  const result = await authApi.checkApiKey(apiKey);

  if (!result.success) {
    throw new AuthenticationError('Invalid API key');
  }

  return result.data!;
}

// ============================================================================
// EMAIL OTP AUTHENTICATION FLOW
// ============================================================================

/**
 * Requests an OTP (One-Time Password) to be sent to the specified email.
 * The OTP will be valid for a limited time and can be used once.
 *
 * @param email - Email address to send OTP to
 * @returns Promise resolving to true if OTP sent successfully, false otherwise
 */
export async function requestEmailOTP(email: string): Promise<boolean> {
  try {
    const authApi = new AuthApi(BASE_URLS.AUTH);
    const result = await authApi.sendOtp(email);
    return result.success;
  } catch (error) {
    console.error('❌ Error requesting OTP:', error);
    return false;
  }
}

/**
 * Verifies an OTP code and retrieves a sign-in token.
 * The sign-in token can be used to generate an API key.
 *
 * @param email - Email address the OTP was sent to
 * @param pin - The OTP code received via email
 * @returns Promise resolving to sign-in token or null if verification failed
 */
export async function verifyOTPAndGetToken(email: string, pin: string): Promise<string | null> {
  try {
    const authApi = new AuthApi(BASE_URLS.AUTH);
    const result = await authApi.verifyOtp(email, pin);
    return result.success ? result.data!.signInToken : null;
  } catch (error) {
    console.error('❌ Error verifying OTP:', error);
    return null;
  }
}

/**
 * Generates a permanent API key using a sign-in token.
 * The sign-in token is obtained from successful OTP verification.
 *
 * @param signInToken - Token obtained from OTP verification
 * @returns Promise resolving to API key or null if generation failed
 */
export async function generateApiKey(signInToken: string): Promise<string | null> {
  try {
    const authApi = new AuthApi(BASE_URLS.AUTH);
    const result = await authApi.getApiKey(signInToken);
    return result.success ? result.data!.apiKey : null;
  } catch (error) {
    console.error('❌ Error generating API key:', error);
    return null;
  }
}
