/**
 * Centralized CLI utilities for consistent error handling and output management
 */

import { AuthenticationError } from '../errors/auth.error.js';
import { isUpdateAvailable, printUpdateWarning } from './version-check.js';
import { getCliVersion } from './package-root.js';
import {
  trackCommand,
  shutdownAnalytics,
  showTelemetryNoticeIfNeeded,
  enrichAnalyticsContext,
} from '../services/analytics.js';
import { hintsDisabled, writeTip, writeNextStep, writeHintBlock } from './hints.js';
import type { NextStepOptions, HintBlockLine } from './hints.js';

// Re-export hint primitives so existing call sites can keep importing from
// `utils/cli.js`. The implementations live in `utils/hints.ts` (a pure
// module) so they're testable without the `import.meta.url` machinery
// below.
export { hintsDisabled, writeTip, writeNextStep, writeHintBlock };
export type { NextStepOptions, HintBlockLine };

/**
 * Global state for CI mode
 * When true, interactive prompts will throw errors instead of silently returning null
 */
let isCiMode = false;

/**
 * Set CI mode flag
 */
export function setCiMode(enabled: boolean): void {
  isCiMode = enabled;
}

/**
 * Check if CI mode is enabled
 */
export function isCiModeEnabled(): boolean {
  return isCiMode;
}

/**
 * Await the background version check and print a warning if outdated.
 * Silently catches any errors from the check itself.
 */
async function showUpdateWarningIfNeeded(
  versionCheckPromise: Promise<{ available: boolean; latest: string | null } | null>
): Promise<void> {
  try {
    const result = await versionCheckPromise;
    if (result?.available && result.latest) {
      printUpdateWarning(getCliVersion(), result.latest);
    }
  } catch {
    // Silently ignore version check failures
  }
}

/**
 * Options for {@link withErrorHandling}.
 */
export interface WithErrorHandlingOptions {
  /**
   * Optional hint provider invoked once when the command throws a generic
   * (non-auth, non-Ctrl+C) error. The returned string is rendered as
   * `💡 <hint>` on stderr, immediately after the standard
   * `❌ Error during <command>:` line. Used by command authors to suggest
   * a contextual `lua logs` command. Return `null` to skip.
   *
   * Errors thrown inside the hint provider are swallowed so a buggy
   * provider never replaces the original error in the UX.
   */
  onError?: (err: Error) => string | null | undefined;
}

/**
 * Wraps a command function with standardized error handling
 * Handles SIGINT (Ctrl+C) gracefully and provides consistent error messages.
 * Also runs a background version check and warns if an update is available.
 *
 * @param opts.onError Optional hint provider; see {@link WithErrorHandlingOptions}.
 */
export async function withErrorHandling<T>(
  commandFn: () => Promise<T>,
  commandName: string,
  opts?: WithErrorHandlingOptions
): Promise<T> {
  showTelemetryNoticeIfNeeded();
  await enrichAnalyticsContext();
  const startTime = Date.now();

  // Start version check in background (non-blocking, runs in parallel with command)
  // Skip for the 'update' command (it handles version checking itself)
  const versionCheckPromise =
    commandName !== 'update' ? isUpdateAvailable(getCliVersion()).catch(() => null) : Promise.resolve(null);

  try {
    const result = await commandFn();

    trackCommand({
      commandName,
      success: true,
      durationMs: Date.now() - startTime,
      cliVersion: getCliVersion(),
    });

    await showUpdateWarningIfNeeded(versionCheckPromise);
    await shutdownAnalytics();
    return result;
  } catch (error: any) {
    if (error.name === 'ExitPromptError') {
      trackCommand({
        commandName,
        success: true,
        durationMs: Date.now() - startTime,
        cliVersion: getCliVersion(),
        properties: { cancelled: true },
      });
      await shutdownAnalytics();
      process.exit(0);
    }

    trackCommand({
      commandName,
      success: false,
      durationMs: Date.now() - startTime,
      cliVersion: getCliVersion(),
      error: error.message,
      properties: { is_auth_error: AuthenticationError.isAuthenticationError(error) },
    });

    if (AuthenticationError.isAuthenticationError(error)) {
      console.error(`\n❌ ${error.message}`);
      // Tailor the remediation hint to the actual reason — see BAC-202.
      // The same 401 status can mean either "your key is bad" or "your key
      // is fine but you don't own the agentId in lua.skill.yaml". Sending
      // users to `lua auth configure` for the second case is a dead end.
      // Throw sites with richer context (e.g. getToken() listing all three
      // ways to provide a key) set suppressDefaultRemediation to keep the
      // CLI from printing a duplicate, less specific hint after their
      // already-formatted message.
      if (!error.suppressDefaultRemediation) {
        if (error.reason === 'no_agent_access') {
          console.error(
            '\n  Your API key is valid, but it does not have access to the agentId\n' +
              '  configured in lua.skill.yaml. This usually means:\n' +
              '\n' +
              '    • The agentId belongs to a different account or organization\n' +
              '    • The agent was deleted, transferred, or you lost access to it\n' +
              "    • You're using a lua.skill.yaml copied from another project\n" +
              '\n' +
              '  Check the configured agent and switch if needed:\n' +
              '\n' +
              '    ➜  lua agents          (list agents you have access to)\n' +
              '    ➜  lua init            (re-select the agent for this project)\n'
          );
        } else {
          console.error(
            '\n  Re-authenticate or check your API key:\n' +
              '\n' +
              '    ➜  lua auth configure\n' +
              '    ➜  https://admin.heylua.ai\n'
          );
        }
      } else {
        // Add a trailing newline for visual parity with the branches above.
        console.error('');
      }
      await showUpdateWarningIfNeeded(versionCheckPromise);
      await shutdownAnalytics();
      process.exit(1);
    }

    console.error(`❌ Error during ${commandName}:`, error.message);

    if (opts?.onError && !hintsDisabled()) {
      try {
        const hint = opts.onError(error);
        if (hint) {
          console.error(`💡 ${hint}`);
        }
      } catch {
        // Buggy hint provider must never replace the real error.
      }
    }

    await showUpdateWarningIfNeeded(versionCheckPromise);
    await shutdownAnalytics();
    throw new Error(`Error during ${commandName}: ${error.message}`);
  }
}

/**
 * Clears the specified number of lines from the terminal
 * Used to clean up inquirer prompt output ONLY
 * Should NOT be used to clear user input commands
 */
export function clearPromptLines(count: number = 1): void {
  for (let i = 0; i < count; i++) {
    process.stdout.write('\x1b[1A\x1b[2K'); // Move up 1 line and clear it
  }
}

/**
 * Writes a progress message that overwrites the current line
 * Uses carriage return to replace previous progress messages
 */
export function writeProgress(message: string): void {
  // Clear current line and write message (no newline - will be overwritten)
  process.stdout.write('\r\x1b[K' + message);
}

/**
 * Writes a final success message that will remain visible
 * Clears the progress line first, then writes the message with newline
 */
export function writeSuccess(message: string): void {
  // Clear any progress message, write message, and ensure newline
  process.stdout.write('\r\x1b[K' + message + '\n');
}

/**
 * Writes an error message
 * Clears the progress line first, then writes the error with newline
 */
export function writeError(message: string): void {
  // Clear any progress message, write error, and ensure newline
  process.stderr.write('\r\x1b[K' + message + '\n');
}

