import { Product } from '../interfaces/product.js';
import { UserData } from '../interfaces/admin.js';
import { CustomDataAPI, UserDataAPI } from '../types/index.js';
import { CreateCustomDataResponse } from '../interfaces/custom.data.js';

/**
 * Data entry instance class providing a fluent API for managing custom data entries
 * Provides methods for updating and deleting individual data entries
 * Supports direct property access (e.g., entry.fieldName) for accessing data properties
 */
export default class DataEntryInstance {
  data: Record<string, any>;
  id: string;
  collectionName: string;
  score?: number;
  private customDataAPI!: CustomDataAPI; // Use definite assignment assertion

  // Index signature to allow dynamic property access
  [key: string]: any;

  /**
   * Creates a new DataEntryInstance with proxy support for direct property access
   * @param api - The CustomDataAPI instance for making API calls
   * @param entry - The custom data entry response from the API
   * @param collectionName - The name of the collection this entry belongs to
   * @returns Proxied instance that allows direct access to data properties
   */
  constructor(api: CustomDataAPI, entry: CreateCustomDataResponse, collectionName: string) {
    // Ensure data is always an object, never null or undefined
    this.data = entry.data && typeof entry.data === 'object' ? entry.data : {};
    this.id = entry.id;
    this.collectionName = collectionName;
    this.score = entry.score;
    // Make userAPI non-enumerable so it doesn't show up in console.log
    Object.defineProperty(this, 'customDataAPI', {
      value: api,
      writable: true,
      enumerable: false,
      configurable: true,
    });

    // Return a proxy that allows direct property access
    return new Proxy(this, {
      get(target, prop, receiver) {
        // If the property exists on the instance itself, return it
        if (prop in target) {
          return Reflect.get(target, prop, receiver);
        }
        // Otherwise, try to get it from the data object (with null check)
        if (typeof prop === 'string' && target.data && typeof target.data === 'object' && prop in target.data) {
          return target.data[prop];
        }
        return undefined;
      },
      set(target, prop, value, receiver) {
        // Reserved properties that should be set on the instance itself
        const reservedProps = ['data', 'id', 'collectionName', 'score', 'customDataAPI', 'update', 'delete', 'toJSON'];
        if (typeof prop === 'string' && reservedProps.includes(prop)) {
          return Reflect.set(target, prop, value, receiver);
        }
        // All other properties get set on the data object
        if (typeof prop === 'string') {
          // Initialize data object if it doesn't exist
          if (!target.data || typeof target.data !== 'object') {
            target.data = {};
          }
          target.data[prop] = value;
          return true;
        }
        return false;
      },
      has(target, prop) {
        // Check if property exists on instance or in data (with null check)
        if (prop in target) {
          return true;
        }
        if (typeof prop === 'string' && target.data && typeof target.data === 'object') {
          return prop in target.data;
        }
        return false;
      },
      ownKeys(target) {
        // Return both instance keys and data keys (with null check)
        const instanceKeys = Reflect.ownKeys(target);
        const dataKeys = target.data && typeof target.data === 'object' ? Object.keys(target.data) : [];
        return [...new Set([...instanceKeys, ...dataKeys])];
      },
      getOwnPropertyDescriptor(target, prop) {
        // First check if it's an instance property
        const instanceDesc = Reflect.getOwnPropertyDescriptor(target, prop);
        if (instanceDesc) {
          return instanceDesc;
        }
        // Then check if it's a data property (with null check)
        if (typeof prop === 'string' && target.data && typeof target.data === 'object' && prop in target.data) {
          return {
            configurable: true,
            enumerable: true,
            writable: true,
            value: target.data[prop],
          };
        }
        return undefined;
      },
    });
  }

  /**
   * Custom toJSON method to control what gets serialized when logging
   * @returns Serialized data entry including score if available
   */
  toJSON(): Record<string, any> {
    return {
      ...this.data,
      score: this.score,
      id: this.id,
      collectionName: this.collectionName,
    };
  }

  /**
   * Custom inspect method for Node.js console.log
   * @returns Formatted data entry for console output
   */
  [Symbol.for('nodejs.util.inspect.custom')](): Record<string, any> {
    return {
      ...this.data,
      score: this.score,
      id: this.id,
      collectionName: this.collectionName,
    };
  }

  /**
   * Updates the custom data entry
   * @param data - The data fields to update (partial update supported)
   * @param searchText - Optional new search text for semantic search indexing
   * @returns Promise resolving to the updated data
   * @throws Error if the update fails
   */
  async update(data: Record<string, any>, searchText?: string): Promise<Record<string, any>> {
    try {
      await this.customDataAPI.update(this.collectionName, this.id, data, searchText);
      this.data = { ...this.data, ...data };
      return this.data;
    } catch (error) {
      throw new Error('Failed to update custom data entry');
    }
  }

  /**
   * Deletes the custom data entry
   * @returns Promise resolving to true if deletion was successful
   * @throws Error if the deletion fails
   */
  async delete(): Promise<boolean> {
    try {
      await this.customDataAPI.delete(this.collectionName, this.id);
      return true;
    } catch (error) {
      throw new Error('Failed to delete custom data entry');
    }
  }

  /**
   * Saves the data entry
   * @param searchText - Optional search text for vector search indexing
   * @returns Promise resolving to true if saving was successful
   * @throws Error if the save operation fails
   */
  async save(searchText?: string): Promise<boolean> {
    try {
      await this.customDataAPI.update(this.collectionName, this.id, this.data, searchText);
      return true;
    } catch (error) {
      throw new Error('Failed to save data entry');
    }
  }
}
