import type { AgentInvocationInput, AgentInvocationOutput } from '@lua/shared-types';
import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';

/**
 * Wire body for POST `/chat/generate/:agentId` — mirrors the subset of
 * `ChatMessageDto` that lua-core accepts.
 */
interface ChatGenerateBody {
  messages: Array<{ type: 'text'; text: string } | Record<string, unknown>>;
  navigate: boolean;
  systemPrompt?: string;
  runtimeContext?: string;
  threadId?: string;
}

/**
 * Thin wrapper around `POST /chat/generate/:agentId` used by the lua-cli
 * sandbox's `Agents.invoke`. Mirrors the HTTP pattern `lua chat` already uses
 * — no new endpoint on lua-api / lua-core is required.
 */
export default class AgentsApiService extends HttpClient {
  constructor(
    baseUrl: string,
    private readonly apiKey: string
  ) {
    super(baseUrl);
  }

  async invoke(targetAgentId: string, body: AgentInvocationInput): Promise<ApiResponse<AgentInvocationOutput>> {
    const channel = body.channel ?? 'agent-invocation';
    const query = new URLSearchParams({ channel });
    if (body.identifier) query.set('identifier', body.identifier);
    const chatBody = this.toChatGenerateBody(body);
    return this.httpPost<AgentInvocationOutput>(`/chat/generate/${targetAgentId}?${query.toString()}`, chatBody, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Sandbox overload: mirrors the `AI.generate` pattern where the simplified
   * `(prompt)` call returns plain text and the `(input)` call returns the
   * full structured output.
   */
  async invokeForSandbox(
    targetAgentId: string,
    promptOrInput: string | AgentInvocationInput
  ): Promise<string | AgentInvocationOutput> {
    const input: AgentInvocationInput = typeof promptOrInput === 'string' ? { prompt: promptOrInput } : promptOrInput;

    const result = await this.invoke(targetAgentId, input);
    if (!result.success) {
      throw new Error(result.error?.message || 'Agent invocation failed');
    }
    if (!result.data) {
      throw new Error('Agent invocation failed: empty response');
    }

    return typeof promptOrInput === 'string' ? (result.data.text ?? '') : result.data;
  }

  private toChatGenerateBody(body: AgentInvocationInput): ChatGenerateBody {
    const messages = body.messages
      ? (body.messages as ChatGenerateBody['messages'])
      : [{ type: 'text' as const, text: body.prompt ?? '' }];

    return {
      messages,
      navigate: false,
      ...(body.systemPrompt !== undefined ? { systemPrompt: body.systemPrompt } : {}),
      ...(body.runtimeContext !== undefined ? { runtimeContext: body.runtimeContext } : {}),
      ...(body.threadId !== undefined ? { threadId: body.threadId } : {}),
    };
  }
}
