/**
 * Lazy-Loaded API Instances
 * Provides singleton instances of API services with lazy initialization
 */

import { BASE_URLS } from '../config/constants.js';
import { getCredentials } from './credentials.js';
import ProductApiService from './products.api.service.js';
import BasketApiService from './basket.api.service.js';
import OrderApiService from './order.api.service.js';
import UserDataApiService from './user.data.api.service.js';
import CustomDataApiService from './custom.data.api.service.js';
import WebhookApi from './webhook.api.service.js';
import JobApi from './job.api.service.js';
import AiApiService from './ai.api.service.js';
import AgentsApiService from './agents.api.service.js';
import WhatsAppTemplatesApiService from './whatsapp-templates.api.service.js';
import CdnApi from './cdn.api.service.js';
import DeveloperApi from './developer.api.service.js';
import VoiceApi from './voice.api.service.js';
import { JobInstance } from '../instances/job.instance.js';

/**
 * Singleton instances (lazy-loaded)
 */
let _userInstance: UserDataApiService | null = null;
let _dataInstance: CustomDataApiService | null = null;
let _productsInstance: ProductApiService | null = null;
let _basketsInstance: BasketApiService | null = null;
let _orderInstance: OrderApiService | null = null;
let _webhookInstance: WebhookApi | null = null;
let _jobInstance: JobApi | null = null;
let _aiInstance: AiApiService | null = null;
let _agentsInstance: AgentsApiService | null = null;
let _whatsAppTemplatesInstance: WhatsAppTemplatesApiService | null = null;
let _cdnInstance: CdnApi | null = null;
let _developerInstance: DeveloperApi | null = null;
let _voiceInstance: VoiceApi | null = null;

/**
 * Gets or creates User Data API instance.
 * Instance is created once and reused for subsequent calls.
 *
 * @returns UserDataApiService instance
 */
export async function getUserInstance(): Promise<UserDataApiService> {
  if (!_userInstance) {
    const creds = await getCredentials();
    _userInstance = new UserDataApiService(BASE_URLS.API, creds.apiKey, creds.agentId);
  }
  return _userInstance;
}

