/**
 * Gets or creates Device API instance.
 */
let _deviceInstance: any = null;
export async function getDeviceInstance(): Promise<any> {
  if (!_deviceInstance) {
    const { default: DeviceApi } = await import('./device.api.service.js');
    const creds = await getCredentials();
    _deviceInstance = new DeviceApi(BASE_URLS.API, creds.apiKey, creds.agentId);
  }
  return _deviceInstance;
}

