/**
 * Clears all cached API instances.
 * Useful for testing or when credentials change.
 */
export function clearAllInstances(): void {
  _userInstance = null;
  _dataInstance = null;
  _productsInstance = null;
  _basketsInstance = null;
  _orderInstance = null;
  _webhookInstance = null;
  _jobInstance = null;
  _aiInstance = null;
  _agentsInstance = null;
  _whatsAppTemplatesInstance = null;
  _cdnInstance = null;
  _developerInstance = null;
  _voiceInstance = null;
}
