/**
 * Resolves lua-cli's package root by walking up from `import.meta.url` until
 * it finds a `package.json` with `"name": "lua-cli"`.
 *
 * Works identically in three modes:
 *   - jest/tsc (src/): walks up from src/utils/package-root.ts
 *   - bundled dist (esm): walks up from dist/<entry>.js
 *   - end-user install: walks up from node_modules/lua-cli/dist/<entry>.js
 *
 * This is the single source of truth for "where is lua-cli on disk." All
 * package-relative resources (version, template/, vendored zod bundle) go
 * through here instead of inlining `__dirname/../../<thing>` walks at call
 * sites — those break when the bundler flattens the dist structure.
 */

import { readFileSync, existsSync } from 'fs';
import { fileURLToPath, pathToFileURL } from 'url';
import { dirname, join } from 'path';

let cachedRoot: string | null = null;
let cachedPkg: { name: string; version: string; [k: string]: unknown } | null = null;

function locate(): { root: string; pkg: typeof cachedPkg } {
  if (cachedRoot && cachedPkg) return { root: cachedRoot, pkg: cachedPkg };

  let dir = dirname(fileURLToPath(import.meta.url));
  while (true) {
    const candidate = join(dir, 'package.json');
    if (existsSync(candidate)) {
      try {
        const parsed = JSON.parse(readFileSync(candidate, 'utf8'));
        if (parsed?.name === 'lua-cli') {
          cachedRoot = dir;
          cachedPkg = parsed;
          return { root: dir, pkg: parsed };
        }
      } catch {
        // Malformed package.json — keep walking.
      }
    }
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  throw new Error('Could not locate lua-cli package root from ' + fileURLToPath(import.meta.url));
}

export function getPackageRoot(): string {
  return locate().root;
}

export function getPackageJson(): { name: string; version: string; [k: string]: unknown } {
  return locate().pkg!;
}

export function getCliVersion(): string {
  try {
    return locate().pkg!.version;
  } catch {
    return '0.0.0';
  }
}

export function getTemplateDir(): string {
  return join(getPackageRoot(), 'template');
}

export function getZodRuntimeUrl(): URL {
  // Vendored zod bundle lives at dist/zod-runtime.mjs in published installs.
  // Emitted by scripts/build-vendor.mjs. Use pathToFileURL (not raw string
  // concat) so the resulting URL is valid on Windows, where path.join
  // returns backslash-separated paths.
  return pathToFileURL(join(getPackageRoot(), 'dist', 'zod-runtime.mjs'));
}
