/**
 * Authentication Error
 * Thrown when API requests fail with 401 Unauthorized status
 */

/**
 * Why a 401 happened. The CLI prints different guidance for each:
 * - `invalid_credentials`: API key is missing/invalid/expired → suggest `lua auth configure`.
 * - `no_agent_access`: API key is fine, but the user does not have access to the
 *   agentId in the request → suggest checking `lua.skill.yaml`'s `agent.agentId`.
 * - `unknown`: 401 with no parseable body (treat conservatively as credentials).
 */
export type AuthErrorReason = 'invalid_credentials' | 'no_agent_access' | 'unknown';

export class AuthenticationError extends Error {
  public readonly statusCode: number = 401;
  public readonly isAuthenticationError: boolean = true;
  public readonly reason: AuthErrorReason;
  public readonly serverMessage?: string;
  /**
   * If true, the error message already contains complete remediation steps
   * and `withErrorHandling` should not append its own hint block. Use this
   * when the throw site has more context about the right fix than the
   * generic per-reason hints (e.g. `getToken()` listing all three ways to
   * configure a key — keychain, env var, .env file).
   */
  public readonly suppressDefaultRemediation: boolean;

  constructor(
    message: string = 'Invalid API key',
    reason: AuthErrorReason = 'unknown',
    serverMessage?: string,
    suppressDefaultRemediation: boolean = false
  ) {
    super(message);
    this.name = 'AuthenticationError';
    this.reason = reason;
    this.serverMessage = serverMessage;
    this.suppressDefaultRemediation = suppressDefaultRemediation;

    // Maintains proper stack trace for where our error was thrown (only available on V8)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, AuthenticationError);
    }
  }

  /**
   * Checks if an error is an AuthenticationError
   * @param error - The error to check
   * @returns True if the error is an AuthenticationError
   */
  static isAuthenticationError(error: unknown): error is AuthenticationError {
    return (
      error instanceof AuthenticationError ||
      (error instanceof Error && 'isAuthenticationError' in error && (error as any).isAuthenticationError === true)
    );
  }
}
