import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';
import {
  CreateJobDTO,
  Job,
  JobVersion,
  JobExecution,
  PushJobVersionDTO,
  UpdateJobVersionDTO,
  GetJobsResponseData,
  GetJobExecutionsResponseData,
  DeleteJobResponseData,
  UpdateJobMetadataResponseData,
} from '../interfaces/jobs.js';
import { JobInstance } from '../instances/job.instance.js';

/**
 * Job API Service
 * Handles all job-related API calls
 */
export default class JobApi extends HttpClient {
  public apiKey: string;
  public agentId: string;

  /**
   * Creates an instance of JobApi
   * @param baseUrl - The base URL for the API
   * @param apiKey - The API key for authentication
   * @param agentId - The unique identifier of the agent
   */
  constructor(baseUrl: string, apiKey: string, agentId: string) {
    super(baseUrl);
    this.apiKey = apiKey;
    this.agentId = agentId;
  }

  /**
   * Retrieves all jobs for the agent
   * @returns Promise resolving to an ApiResponse containing an array of jobs with their versions
   * @throws Error if the API request fails or the agent is not found
   */
  async getJobs(options: { includeDynamic?: boolean } = {}): Promise<ApiResponse<GetJobsResponseData>> {
    const queryParams = new URLSearchParams();
    if (options.includeDynamic) {
      queryParams.append('includeDynamic', 'true');
    }

    const url = `/developer/jobs/${this.agentId}?${queryParams.toString()}`;

    return this.httpGet<GetJobsResponseData>(url, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Retrieves all jobs for the agent as JobInstance array
   * @param options - Optional configuration
   * @param options.includeDynamic - Include dynamically created jobs (default: false)
   * @returns Promise resolving to an array of JobInstance
   * @throws Error if the API request fails
   */
  async getAll(options: { includeDynamic?: boolean } = {}): Promise<JobInstance[]> {
    const response = await this.getJobs(options);
    if (response.success && response.data?.jobs) {
      return response.data.jobs.map((job) => new JobInstance(this, job));
    }
    throw new Error(response.error?.message || 'Failed to get all jobs');
  }

  /**
   * Retrieves a job by its unique identifier
   * @param jobId - The unique identifier of the job to retrieve
   * @returns Promise resolving to an JobInstance representing the job
   * @throws Error if the job is not found or the request fails
   */
  async getJob(jobId: string): Promise<JobInstance> {
    const response = await this.httpGet<Job>(`/developer/jobs/${this.agentId}/${jobId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
    if (response.success && response.data) {
      return new JobInstance(this, response.data);
    }
    throw new Error(response.error?.message || 'Failed to get job');
  }

  /**
   * Creates a new job for the agent.
   * Optionally creates initial version and activates the job in one call.
   *
   * @param jobData - The job data including name, description, schedule, and optional version
   * @param jobData.version - If provided, creates first version automatically
   * @param jobData.activate - If true, activates the job immediately
   * @returns Promise resolving to an ApiResponse containing the full job with versions
   * @throws Error if the job creation fails or validation errors occur
   */
  async createJob(jobData: CreateJobDTO): Promise<ApiResponse<Job>> {
    return this.httpPost<Job>(`/developer/jobs/${this.agentId}`, jobData, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Creates a new job for the agent and returns a JobInstance.
   * Supports automatic version creation and activation.
   *
   * @param jobData - The job data including name, description, schedule, and optional version
   * @param jobData.version - If provided, creates first version automatically
   * @param jobData.activate - If true, activates the job immediately
   * @returns Promise resolving to a JobInstance containing the created job details
   * @throws Error if the job creation fails or validation errors occur
   */
  async createJobInstance(jobData: CreateJobDTO): Promise<JobInstance> {
    const response = await this.httpPost<Job>(`/developer/jobs/${this.agentId}`, jobData, {
      Authorization: `Bearer ${this.apiKey}`,
    });
    if (response.success && response.data) {
      return new JobInstance(this, response.data);
    }
    throw new Error(response.error?.message || 'Failed to create job');
  }

  /**
   * Pushes a new version of a job to production
   * @param jobId - The unique identifier of the job
   * @param versionData - The version data including code, configuration, and metadata
   * @returns Promise resolving to an ApiResponse containing the full job version
   * @throws Error if the job is not found or the push operation fails
   */
  async pushJob(jobId: string, versionData: PushJobVersionDTO): Promise<ApiResponse<JobVersion>> {
    return this.httpPost<JobVersion>(`/developer/jobs/${this.agentId}/${jobId}/version`, versionData, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Pushes a new development/sandbox version of a job for testing
   * @param jobId - The unique identifier of the job
   * @param versionData - The version data including code, configuration, and metadata
   * @returns Promise resolving to an ApiResponse containing the full job version
   * @throws Error if the job is not found or the push operation fails
   */
  async pushDevJob(jobId: string, versionData: PushJobVersionDTO): Promise<ApiResponse<JobVersion>> {
    return this.httpPost<JobVersion>(`/developer/jobs/${this.agentId}/${jobId}/version/sandbox`, versionData, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Updates an existing development/sandbox version of a job
   * @param jobId - The unique identifier of the job
   * @param sandboxVersionId - The unique identifier of the sandbox version to update
   * @param versionData - The updated version data including code, configuration, and metadata
   * @returns Promise resolving to an ApiResponse containing the full updated job version
   * @throws Error if the job or version is not found or the update fails
   */
  async updateDevJob(
    jobId: string,
    sandboxVersionId: string,
    versionData: UpdateJobVersionDTO
  ): Promise<ApiResponse<JobVersion>> {
    return this.httpPut<JobVersion>(
      `/developer/jobs/${this.agentId}/${jobId}/version/sandbox/${sandboxVersionId}`,
      versionData,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Retrieves all versions of a specific job
   * @param jobId - The unique identifier of the job
   * @returns Promise resolving to an ApiResponse containing an array of job versions
   * @throws Error if the job is not found or the request fails
   */
  async getJobVersions(jobId: string): Promise<ApiResponse<JobVersion[]>> {
    return this.httpGet<JobVersion[]>(`/developer/jobs/${this.agentId}/${jobId}/versions`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Publishes a specific version of a job to production
   * @param jobId - The unique identifier of the job
   * @param version - The version identifier to publish
   * @returns Promise resolving to an ApiResponse containing the full updated job
   * @throws Error if the job or version is not found or the publish operation fails
   */
  async publishJobVersion(jobId: string, version: string): Promise<ApiResponse<Job>> {
    return this.httpPost<Job>(
      `/developer/jobs/${this.agentId}/${jobId}/${version}/publish`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Deletes a job and all its versions, or deactivates it if it has versions
   * @param jobId - The unique identifier of the job to delete
   * @returns Promise resolving to an ApiResponse with deletion status
   *   - If deleted is true: job was successfully deleted
   *   - If deleted is false and deactivated is true: job has versions and was deactivated instead
   * @throws Error if the job is not found or the delete operation fails
   */
  async deleteJob(jobId: string): Promise<ApiResponse<DeleteJobResponseData>> {
    return this.httpDelete<DeleteJobResponseData>(`/developer/jobs/${this.agentId}/${jobId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Activates a job (enables it to run on schedule)
   * @param jobId - The unique identifier of the job to activate
   * @returns Promise resolving to an ApiResponse with the full updated job
   * @throws Error if the job is not found or the operation fails
   */
  async activateJob(jobId: string): Promise<ApiResponse<Job>> {
    return this.httpPost<Job>(
      `/developer/jobs/${this.agentId}/${jobId}/activate`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Deactivates a job (disables it from running)
   * @param jobId - The unique identifier of the job to deactivate
   * @returns Promise resolving to an ApiResponse with the full updated job
   * @throws Error if the job is not found or the operation fails
   */
  async deactivateJob(jobId: string): Promise<ApiResponse<Job>> {
    return this.httpPost<Job>(
      `/developer/jobs/${this.agentId}/${jobId}/deactivate`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Manually triggers a job execution (ignores schedule)
   * @param jobId - The unique identifier of the job to trigger
   * @param versionId - The version identifier to execute (optional, defaults to activeVersionId)
   * @returns Promise resolving to an ApiResponse with the execution record
   * @throws Error if the job is not found or the operation fails
   */
  async triggerJob(jobId: string, versionId?: string): Promise<ApiResponse<JobExecution>> {
    const body = versionId ? { versionId } : {};
    return this.httpPost<JobExecution>(`/developer/jobs/${this.agentId}/${jobId}/trigger`, body, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Retrieves execution history for a job
   * @param jobId - The unique identifier of the job
   * @param limit - Maximum number of executions to return (default: 50)
   * @returns Promise resolving to an ApiResponse with execution history
   * @throws Error if the job is not found or the request fails
   */
  async getJobExecutions(jobId: string, limit: number = 50): Promise<ApiResponse<GetJobExecutionsResponseData>> {
    return this.httpGet<GetJobExecutionsResponseData>(
      `/developer/jobs/${this.agentId}/${jobId}/executions?limit=${limit}`,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  /**
   * Updates the metadata of a job
   * @param jobId - The unique identifier of the job
   * @param metadata - The metadata object to update or merge with existing metadata
   * @returns Promise resolving to the updated metadata
   * @throws Error if the job is not found or the metadata update fails
   */
  async updateMetadata(
    jobId: string,
    metadata: Record<string, any>
  ): Promise<ApiResponse<UpdateJobMetadataResponseData>> {
    return this.httpPut<UpdateJobMetadataResponseData>(`/developer/jobs/${this.agentId}/${jobId}/metadata`, metadata, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }
}
