/**
 * CDN API Service
 * Handles file upload and retrieval from the Lua CDN
 */

import { CdnAPI } from '../types/api-contracts.js';
import { CdnUploadResponse } from '../interfaces/cdn.js';

export default class CdnApi implements CdnAPI {
  private baseUrl: string;
  private apiKey: string;

  constructor(baseUrl: string, apiKey: string) {
    this.baseUrl = baseUrl;
    this.apiKey = apiKey;
  }

  /**
   * Uploads a file to the CDN
   * @param file - The file to upload
   * @returns Promise resolving to the file ID
   */
  async upload(file: File): Promise<string> {
    const formData = new FormData();
    formData.append('file', file, file.name);

    const response = await fetch(`${this.baseUrl}/upload`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${this.apiKey}` },
      body: formData,
    });

    if (!response.ok) {
      const error = (await response.json().catch(() => ({}))) as Record<string, any>;
      throw new Error(error.message || `Upload failed: ${response.status}`);
    }

    const data = (await response.json()) as CdnUploadResponse;
    return data.fileId;
  }

  /**
   * Fetches a file from the CDN by its ID
   */
  async get(fileId: string): Promise<File> {
    const response = await fetch(`${this.baseUrl}/${fileId}`);

    if (!response.ok) {
      throw new Error(`File not found: ${response.status}`);
    }

    const contentType = response.headers.get('content-type') || 'application/octet-stream';
    const contentDisposition = response.headers.get('content-disposition') || '';
    const filenameMatch = contentDisposition.match(/filename="?([^"]+)"?/);
    const filename = filenameMatch?.[1] || fileId;

    const blob = await response.blob();
    return new File([blob], filename, { type: contentType });
  }
}
