/**
 * Command Utilities
 * Shared utilities for command initialization and common operations
 */

import { getToken, checkApiKey } from '../services/auth.js';
import { readYamlConfig } from './files.js';
import { writeProgress } from './cli.js';
import { YamlConfig } from '../types/yaml.types.js';

/**
 * Context returned by initializeCommand for use in command handlers
 */
export interface CommandContext {
  config: YamlConfig;
  agentId: string;
  orgId: string;
  apiKey: string;
  userData?: any;
}

/**
 * Loads and returns the API key.
 * Does NOT validate with server — the first actual API call will validate
 * (HttpClient throws AuthenticationError on 401, caught by withErrorHandling).
 *
 * @returns The API key
 * @throws AuthenticationError if no API key found
 */
export function requireAuth(): string {
  return getToken();
}

/**
 * Loads and returns the API key.
 * Does NOT validate with server — lazy validation on first API call.
 *
 * @returns The API key
 * @throws AuthenticationError if no API key found
 */
export function requireAuthOrExit(showProgress: boolean = true): string {
  const apiKey = getToken();
  if (showProgress) {
    writeProgress('✅ Authenticated');
  }
  return apiKey;
}

/**
 * Full command initialization - validates config + loads auth, returns context.
 * Auth is lazy by default — set validateAuth: true when you need userData.
 *
 * @param options - Optional configuration
 * @param options.showProgress - Whether to show progress messages (default: true)
 * @param options.validateAuth - Validate API key with server and fetch userData (default: false)
 * @returns Command context with config, agentId, apiKey, and optionally userData
 */
export async function initializeCommand(
  options: {
    showProgress?: boolean;
    validateAuth?: boolean;
  } = {}
): Promise<CommandContext> {
  const { showProgress = true, validateAuth = false } = options;

  // Validate config exists
  const config = readYamlConfig();
  if (!config) {
    throw new Error('No lua.skill.yaml found. Please run this command from a skill directory.');
  }

  // Validate agent config
  if (!config.agent?.agentId) {
    throw new Error("Missing agentId in skill configuration. Please run 'lua init' first.");
  }

  // Validate org config
  if (!config.agent?.orgId) {
    throw new Error("Missing orgId in skill configuration. Please run 'lua init' first.");
  }

  // Load API key (throws AuthenticationError if missing)
  const apiKey = getToken();

  let userData: any = undefined;
  if (validateAuth) {
    userData = await checkApiKey(apiKey);
  }

  if (showProgress) {
    writeProgress('✅ Authenticated');
  }

  return {
    config,
    agentId: config.agent.agentId,
    orgId: config.agent.orgId,
    apiKey,
    userData,
  };
}
