import { ProductsResponse, ProductFilterOptions } from '../interfaces/product.js';
import { HttpClient } from './http.client.js';
import { ProductAPI } from '../types/index.js';
import { Product } from '../interfaces/product.js';
import { CreateProductResponse } from '../interfaces/product.js';
import { UpdateProductResponse } from '../interfaces/product.js';
import { DeleteProductResponse } from '../interfaces/product.js';
import { SearchProductsResponse } from '../interfaces/product.js';
import ProductInstance from '../instances/product.instance.js';
import ProductPaginationInstance from '../instances/product.pagination.instance.js';
import ProductSearchInstance from '../instances/product.search.instance.js';
/**
 * Product API calls
 */
export default class ProductApi extends HttpClient implements ProductAPI {
  private apiKey: string;
  private agentId: string;

  /**
   * Creates an instance of ProductApi
   * @param baseUrl - The base URL for the API
   * @param apiKey - The API key for authentication
   * @param agentId - The unique identifier of the agent
   */
  constructor(baseUrl: string, apiKey: string, agentId: string) {
    super(baseUrl);
    this.apiKey = apiKey;
    this.agentId = agentId;
  }

  /**
   * Retrieves products for an agent with pagination and optional filtering.
   * Supports both legacy (page, limit) and new (options object) signatures.
   *
   * @example
   * // Legacy: Get products with pagination
   * await products.get(1, 10);
   *
   * // New: Get products with options object
   * await products.get({ page: 2, limit: 20 });
   *
   * // New: Filter products by category
   * await products.get({ filter: { category: "Electronics" } });
   *
   * // New: Filter with MongoDB operators
   * await products.get({ filter: { price: { $lte: 100 }, inStock: true } });
   */
  async get(page?: number, limit?: number): Promise<ProductPaginationInstance>;
  async get(options?: ProductFilterOptions): Promise<ProductPaginationInstance>;
  async get(pageOrOptions?: number | ProductFilterOptions, limitArg?: number): Promise<ProductPaginationInstance> {
    let page: number;
    let limit: number;
    let filter: Record<string, any> | undefined;

    // Check if first argument is a number (legacy signature) or an object (new signature)
    if (typeof pageOrOptions === 'number') {
      page = pageOrOptions;
      limit = limitArg ?? 10;
    } else {
      page = pageOrOptions?.page ?? 1;
      limit = pageOrOptions?.limit ?? 10;
      filter = pageOrOptions?.filter;
    }

    const queryParams = new URLSearchParams();
    queryParams.append('page', page.toString());
    queryParams.append('limit', limit.toString());
    if (filter) {
      queryParams.append('filter', JSON.stringify(filter));
    }

    const response = await this.httpGet<ProductsResponse>(
      `/developer/agents/${this.agentId}/products?${queryParams.toString()}`,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
    if (response.success) {
      return new ProductPaginationInstance(this, response as ProductsResponse);
    }
    throw new Error(response.error?.message || 'Failed to get products');
  }

  /**
   * Retrieves a single product by its unique identifier
   * @param productId - The unique identifier of the product to retrieve
   * @returns Promise resolving to a ProductInstance representing the product
   * @throws Error if the product is not found or the request fails
   */
  async getById(productId: string): Promise<ProductInstance> {
    const response = await this.httpGet<Product>(`/developer/agents/${this.agentId}/products/${productId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
    if (response.success && response.data) {
      return new ProductInstance(this, response.data);
    }
    throw new Error(response.error?.message || 'Failed to get product');
  }

  /**
   * Creates a new product in the agent's catalog
   * @param productData - The product data including name, description, price, images, and metadata
   * @returns Promise resolving to a ProductInstance representing the created product
   * @throws Error if the product creation fails or validation errors occur
   */
  async create(productData: Product): Promise<ProductInstance> {
    const response = await this.httpPost<CreateProductResponse>(
      `/developer/agents/${this.agentId}/products`,
      productData,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
    if (response.success && response.data) {
      return new ProductInstance(this, response.data.product);
    }
    throw new Error(response.error?.message || 'Failed to create product');
  }

  /**
   * Updates an existing product's information
   * @param productData - The product data fields to update (partial update supported)
   * @param productId - The unique identifier of the product to update
   * @returns Promise resolving to an UpdateProductResponse with the updated product details
   * @throws Error if the product is not found or the update fails
   */
  async update(productData: Record<string, any>, productId: string): Promise<UpdateProductResponse> {
    const response = await this.httpPut<UpdateProductResponse>(
      `/developer/agents/${this.agentId}/products`,
      { ...productData, id: productId },
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
    if (response.success && response.data) {
      return response.data;
    }
    throw new Error(response.error?.message || 'Failed to update product');
  }

  /**
   * Deletes a product from the agent's catalog
   * @param productId - The unique identifier of the product to delete
   * @returns Promise resolving to a DeleteProductResponse confirming deletion
   * @throws Error if the product is not found or the deletion fails
   */
  async delete(productId: string): Promise<DeleteProductResponse> {
    const response = await this.httpDelete<DeleteProductResponse>(
      `/developer/agents/${this.agentId}/products/${productId}`,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
    if (response.success && response.data) {
      return response.data;
    }
    throw new Error(response.error?.message || 'Failed to delete product');
  }

  /**
   * Performs semantic search on products using a text query
   * @param searchQuery - The search text to find matching products
   * @param limit - The maximum number of products to return (default: 5)
   * @returns Promise resolving to a ProductSearchInstance containing search results
   * @throws Error if the search fails or the API request is unsuccessful
   */
  async search(searchQuery: string, limit: number = 5): Promise<ProductSearchInstance> {
    const response = await this.httpGet<SearchProductsResponse>(
      `/developer/agents/${this.agentId}/products/search?searchQuery=${encodeURIComponent(searchQuery)}&limit=${limit}`,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
    if (response.success) {
      return new ProductSearchInstance(this, response as unknown as SearchProductsResponse);
    }
    throw new Error(response.error?.message || 'Failed to search products');
  }
}
