import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';
import type { CreateDeviceRequest, DeviceResponse, PushDeviceVersionDTO } from '../interfaces/devices.js';

/**
 * Device API Response Types
 */
export interface DeviceVersion {
  version: string;
  deviceId: string;
  createdAt: string | number;
  isActive?: boolean;
}

export interface GetDevicesResponse {
  devices: DeviceResponse[];
}

export interface CreateDeviceResponse {
  id: string;
  name: string;
  description?: string;
  agentId: string;
}

export interface PushDeviceVersionResponse {
  versionId: string;
  deviceId: string;
  version: string;
  createdAt: string;
}

/**
 * Device API Service
 * Handles all device-related API calls (CRUD, versioning, commands)
 */
export default class DeviceApi extends HttpClient {
  private apiKey: string;
  private agentId: string;

  constructor(baseUrl: string, apiKey: string, agentId: string) {
    super(baseUrl);
    this.apiKey = apiKey;
    this.agentId = agentId;
  }

  async getDevices(): Promise<ApiResponse<GetDevicesResponse>> {
    return this.httpGet<GetDevicesResponse>(`/developer/devices/${this.agentId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  async createDevice(deviceData: CreateDeviceRequest): Promise<ApiResponse<CreateDeviceResponse>> {
    return this.httpPost<CreateDeviceResponse>(`/developer/devices/${this.agentId}`, deviceData, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  async pushDevice(
    deviceId: string,
    versionData: PushDeviceVersionDTO
  ): Promise<ApiResponse<PushDeviceVersionResponse>> {
    return this.httpPost<PushDeviceVersionResponse>(
      `/developer/devices/${this.agentId}/${deviceId}/version`,
      versionData,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  async pushDevDevice(
    deviceId: string,
    versionData: PushDeviceVersionDTO
  ): Promise<ApiResponse<PushDeviceVersionResponse>> {
    return this.httpPost<PushDeviceVersionResponse>(
      `/developer/devices/${this.agentId}/${deviceId}/version/sandbox`,
      versionData,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  async getDeviceVersions(
    deviceId: string
  ): Promise<ApiResponse<{ versions: DeviceVersion[]; activeVersionId?: string }>> {
    return this.httpGet<{ versions: DeviceVersion[]; activeVersionId?: string }>(
      `/developer/devices/${this.agentId}/${deviceId}/versions`,
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  async publishDeviceVersion(
    deviceId: string,
    version: string
  ): Promise<ApiResponse<{ message: string; deviceId: string; activeVersionId: string; publishedAt: string }>> {
    return this.httpPost<{ message: string; deviceId: string; activeVersionId: string; publishedAt: string }>(
      `/developer/devices/${this.agentId}/${deviceId}/${version}/publish`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  async deleteDevice(deviceId: string): Promise<ApiResponse<{ deleted: boolean; message: string }>> {
    return this.httpDelete<{ deleted: boolean; message: string }>(`/developer/devices/${this.agentId}/${deviceId}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  async sendCommand(deviceName: string, command: string, payload: any, timeout?: number): Promise<ApiResponse<any>> {
    return this.httpPost<any>(
      `/developer/devices/${this.agentId}/${deviceName}/command`,
      {
        command,
        payload,
        timeout: timeout || 30000,
      },
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  async getDeviceStatus(deviceName: string): Promise<ApiResponse<{ status: string }>> {
    return this.httpGet<{ status: string }>(`/developer/devices/${this.agentId}/${deviceName}/status`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  async enableDevice(deviceName: string): Promise<ApiResponse<any>> {
    return this.httpPatch<any>(
      `/developer/devices/${this.agentId}/${deviceName}/enable`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }

  async disableDevice(deviceName: string): Promise<ApiResponse<any>> {
    return this.httpPatch<any>(
      `/developer/devices/${this.agentId}/${deviceName}/disable`,
      {},
      {
        Authorization: `Bearer ${this.apiKey}`,
      }
    );
  }
}
