import * as fs from 'fs';
import * as path from 'path';
import pkg from 'js-yaml';
const { load, dump } = pkg;
import { COMPILE_FILES, YAML_FORMAT } from '../config/compile.constants.js';
import { YamlConfig } from '../types/yaml.types.js';
import { skillHandler } from '../primitives/skill.handler.js';

// =============================================================================
// CONFIG VALIDATION
// =============================================================================

/**
 * Validates that configuration has required fields.
 * Acts as a type guard - after calling this, TypeScript knows config is not null.
 *
 * @param config - Skill configuration
 * @throws Error if configuration is invalid
 */
export function validateSkillConfig(config: YamlConfig | null): asserts config is YamlConfig {
  if (!config) {
    throw new Error('No lua.skill.yaml found. Please run this command from a skill directory.');
  }

  if (!config.agent?.agentId) {
    throw new Error('Missing agentId in skill configuration');
  }

  // If skills are defined, they must have skillIds (i.e. been compiled and pushed)
  const skills = skillHandler.getFromYaml(config);
  if (skills.length > 0 && !skills.some((s) => s.skillId)) {
    throw new Error('Skills are missing skillId. Please compile and push your skill first.');
  }
}

/**
 * Copies template files to target directory.
 *
 * @param templateDir - Source template directory
 * @param targetDir - Target directory to copy to
 * @param includeExamples - Whether to include the examples/ directory (default: false)
 * @param skipSrcDir - Whether to skip the src/ directory (for backup restoration, default: false)
 */
export function copyTemplateFiles(
  templateDir: string,
  targetDir: string,
  includeExamples: boolean = false,
  skipSrcDir: boolean = false
): void {
  const files = fs.readdirSync(templateDir);

  for (const file of files) {
    // Skip node_modules and package-lock.json to avoid circular dependencies
    if (file === 'node_modules' || file === 'package-lock.json') {
      continue;
    }

    // Skip examples/ by default (user can include with --with-examples flag)
    if (file === 'examples' && !includeExamples) {
      continue;
    }

    // Skip src/ directory if sources were restored from backup
    if (file === 'src' && skipSrcDir) {
      continue;
    }

    const srcPath = path.join(templateDir, file);
    const destPath = path.join(targetDir, file);

    if (fs.statSync(srcPath).isDirectory()) {
      fs.mkdirSync(destPath, { recursive: true });
      copyTemplateFiles(srcPath, destPath, includeExamples, skipSrcDir);
    } else if (file === 'package.json') {
      // Special handling for package.json to update lua-cli version
      updatePackageJson(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

function updatePackageJson(srcPath: string, destPath: string): void {
  const templatePackageJson = JSON.parse(fs.readFileSync(srcPath, 'utf8'));
  fs.writeFileSync(destPath, JSON.stringify(templatePackageJson, null, 2) + '\n');
}

/**
 * Reads the lua.skill.yaml configuration file from the current working directory.
 *
 * @returns The parsed YAML config or null if file doesn't exist
 */
export function readYamlConfig(): YamlConfig | null {
  const yamlPath = path.join(process.cwd(), COMPILE_FILES.LUA_SKILL_YAML);

  if (!fs.existsSync(yamlPath)) {
    return null;
  }

  const yamlContent = fs.readFileSync(yamlPath, 'utf8');
  return load(yamlContent) as YamlConfig;
}

/**
 * Update only the agent information in an existing YAML file
 */
export function updateYamlAgent(agentId: string, orgId: string): void {
  const config = readYamlConfig();

  if (!config) {
    throw new Error('lua.skill.yaml not found');
  }

  // Update agent information
  config.agent = config.agent || {};
  config.agent.agentId = agentId;
  config.agent.orgId = orgId;

  writeYamlConfig(config);
}

/**
 * Ensures a given entry is present in the project's .gitignore file.
 * If .gitignore doesn't exist, creates it. If the entry already exists, does nothing.
 * Inserts the entry right after a reference line (e.g. "dist/" -> "dist-v2/" after it).
 *
 * @param rootDir - Project root directory
 * @param entry - The gitignore entry to ensure (e.g. "dist-v2/")
 * @param afterEntry - Optional entry after which to insert (falls back to appending)
 */
export function ensureGitignored(rootDir: string, entry: string, afterEntry?: string): void {
  const gitignorePath = path.join(rootDir, '.gitignore');

  if (!fs.existsSync(gitignorePath)) {
    fs.writeFileSync(gitignorePath, `${entry}\n`);
    return;
  }

  const content = fs.readFileSync(gitignorePath, 'utf8');
  const lines = content.split('\n');

  // Already present
  if (lines.some((line) => line.trim() === entry)) {
    return;
  }

  // Try to insert after the reference entry
  if (afterEntry) {
    const idx = lines.findIndex((line) => line.trim() === afterEntry);
    if (idx !== -1) {
      lines.splice(idx + 1, 0, entry);
      fs.writeFileSync(gitignorePath, lines.join('\n'));
      return;
    }
  }

  // Fallback: append to end
  const trimmed = content.endsWith('\n') ? content : content + '\n';
  fs.writeFileSync(gitignorePath, trimmed + entry + '\n');
}

/**
 * Checks if .env file exists in the current working directory.
 *
 * @returns True if .env file exists
 */
export function hasEnvFile(): boolean {
  return fs.existsSync(path.join(process.cwd(), '.env'));
}

/**
 * Writes a YAML config file with consistent formatting.
 * Uses yamlKeySorter by default for consistent key ordering.
 *
 * @param config - The configuration object to write
 * @param filePath - Optional custom file path (defaults to lua.skill.yaml in cwd)
 * @param options - Optional YAML dump options
 */
export function writeYamlConfig(
  config: YamlConfig,
  filePath?: string,
  options?: {
    sortKeys?: boolean | ((a: string, b: string) => number) | false;
    replacer?: (key: string, value: any) => any;
  }
): void {
  const yamlPath = filePath || path.join(process.cwd(), COMPILE_FILES.LUA_SKILL_YAML);

  // Use yamlKeySorter by default unless explicitly disabled with false
  const sortKeys = options?.sortKeys === false ? false : (options?.sortKeys ?? yamlKeySorter);

  const yamlContent = dump(config, {
    indent: YAML_FORMAT.INDENT,
    lineWidth: YAML_FORMAT.LINE_WIDTH,
    noRefs: YAML_FORMAT.NO_REFS,
    sortKeys,
    replacer:
      options?.replacer ||
      ((key: string, value: any) => {
        // Replace undefined values with empty strings by default
        return value === undefined ? '' : value;
      }),
  });

  fs.writeFileSync(yamlPath, yamlContent);
}

/**
 * Standard YAML key sort order for lua.skill.yaml
 */
export const YAML_KEY_ORDER = [
  'agent',
  'skills',
  'webhooks',
  'jobs',
  'preprocessors',
  'postprocessors',
  'mcpServers',
  'skill',
];

/**
 * Sort function for YAML keys to maintain consistent ordering
 */
export function yamlKeySorter(a: string, b: string): number {
  const aIndex = YAML_KEY_ORDER.indexOf(a);
  const bIndex = YAML_KEY_ORDER.indexOf(b);
  if (aIndex !== -1 && bIndex !== -1) return aIndex - bIndex;
  if (aIndex !== -1) return -1;
  if (bIndex !== -1) return 1;
  return a.localeCompare(b);
}
