import { aiGenerateInputFromSimplified, type AiGenerateInput, type AiGenerateOutput } from '@lua/shared-types';
import type { UserContent } from 'ai';
import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';

export const aiGenerateSimplifiedToBody = aiGenerateInputFromSimplified;

/**
 * Proxies isolated AI generation to lua-api (server-side Gemini + usage).
 */
export default class AiApiService extends HttpClient {
  constructor(
    baseUrl: string,
    private readonly apiKey: string,
    private readonly agentId: string
  ) {
    super(baseUrl);
  }

  async generate(body: AiGenerateInput): Promise<ApiResponse<AiGenerateOutput>> {
    return this.httpPost<AiGenerateOutput>(`/developer/ai/${this.agentId}/generate`, body, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Handles the simplified-vs-full-options branching for `AI.generate`.
   * Returns plain text for the simplified overload, full output for the options overload.
   */
  async generateForSandbox(
    promptOrOptions: string | AiGenerateInput,
    content?: UserContent
  ): Promise<string | AiGenerateOutput> {
    if (typeof promptOrOptions === 'string') {
      const result = await this.generate(aiGenerateInputFromSimplified(promptOrOptions, content));
      if (!result.success) {
        throw new Error(result.error?.message || 'AI generation failed');
      }
      return result.data?.text ?? '';
    }
    const result = await this.generate(promptOrOptions);
    if (!result.success) {
      throw new Error(result.error?.message || 'AI generation failed');
    }
    if (!result.data) {
      throw new Error('AI generation failed: empty response');
    }
    return result.data;
  }
}
