/**
 * Backup API Service
 *
 * Handles all backup-related API calls using S3 blob storage.
 * Content is stored in S3, keyed by content hash for deduplication.
 */

import { HttpClient } from './http.client.js';
import { ApiResponse } from '../interfaces/common.js';
import {
  BackupMetadata,
  BackupManifest,
  BackupExistsResponse,
  CheckBlobsRequest,
  CheckBlobsResponse,
  SaveManifestRequest,
  GetBlobUrlsRequest,
  GetBlobUrlsResponse,
} from '../interfaces/backup.js';

/**
 * Backup API client for project source backup operations
 */
export default class BackupApi extends HttpClient {
  private apiKey: string;
  private agentId: string;

  /**
   * Creates an instance of BackupApi
   * @param baseUrl - The base URL for the API
   * @param apiKey - The API key for authentication
   * @param agentId - The unique identifier of the agent
   */
  constructor(baseUrl: string, apiKey: string, agentId: string) {
    super(baseUrl);
    this.apiKey = apiKey;
    this.agentId = agentId;
  }

  // ===========================================================================
  // BLOB OPERATIONS (S3)
  // ===========================================================================

  /**
   * Check which blobs exist in S3.
   * Called first to determine which files need to be uploaded.
   *
   * @param hashes - Array of content hashes to check
   * @returns Promise resolving to missing/existing hash lists
   */
  async checkBlobsExist(hashes: string[]): Promise<ApiResponse<CheckBlobsResponse>> {
    const data: CheckBlobsRequest = { hashes };
    return this.httpPost<CheckBlobsResponse>(`/developer/agents/${this.agentId}/backup/check-blobs`, data, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Get presigned URLs for downloading blobs from S3.
   * Used by download to fetch files in parallel directly from S3.
   *
   * @param hashes - Array of content hashes to get URLs for
   * @returns Promise resolving to map of hash -> presigned URL
   */
  async getBlobUrls(hashes: string[]): Promise<ApiResponse<GetBlobUrlsResponse>> {
    const data: GetBlobUrlsRequest = { hashes };
    return this.httpPost<GetBlobUrlsResponse>(`/developer/agents/${this.agentId}/backup/blob-urls`, data, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Get presigned URLs for uploading blobs directly to S3.
   * Used by push to upload files in parallel directly to S3, bypassing the server.
   *
   * @param hashes - Array of content hashes to get upload URLs for
   * @returns Promise resolving to map of hash -> presigned upload URL
   */
  async getBlobUploadUrls(hashes: string[]): Promise<ApiResponse<GetBlobUrlsResponse>> {
    const data: GetBlobUrlsRequest = { hashes };
    return this.httpPost<GetBlobUrlsResponse>(`/developer/agents/${this.agentId}/backup/blob-upload-urls`, data, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  // ===========================================================================
  // MANIFEST OPERATIONS (MongoDB)
  // ===========================================================================

  /**
   * Save backup manifest after blobs are uploaded.
   * Final step in the backup flow.
   *
   * @param data - Manifest data with file references
   * @returns Promise resolving to backup metadata
   */
  async saveManifest(data: SaveManifestRequest): Promise<ApiResponse<BackupMetadata>> {
    return this.httpPost<BackupMetadata>(`/developer/agents/${this.agentId}/backup/manifest`, data, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Get backup metadata without file list.
   * Used to check if backup exists and get basic info.
   *
   * @returns Promise resolving to backup metadata
   */
  async getBackupMetadata(): Promise<ApiResponse<BackupMetadata>> {
    return this.httpGet<BackupMetadata>(`/developer/agents/${this.agentId}/backup`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Get backup manifest with file list.
   * Use getBlobUrls to get download URLs for the content.
   *
   * @returns Promise resolving to backup manifest with file refs
   */
  async getBackupManifest(): Promise<ApiResponse<BackupManifest>> {
    return this.httpGet<BackupManifest>(`/developer/agents/${this.agentId}/backup/manifest`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }

  /**
   * Check if backup with given hash exists.
   * Allows skipping upload if backup is already up-to-date.
   *
   * @param hash - Project hash to check
   * @returns Promise resolving to existence check result
   */
  async checkBackupExists(hash: string): Promise<ApiResponse<BackupExistsResponse>> {
    return this.httpGet<BackupExistsResponse>(`/developer/agents/${this.agentId}/backup/check/${hash}`, {
      Authorization: `Bearer ${this.apiKey}`,
    });
  }
}
